
'use strict';
module.exports = [
  { id:"ana_1", text:"The axillary nerve (C5,C6) winds around the surgical neck of humerus. Which muscle does it NOT supply?", options:["Deltoid","Teres minor","Teres major","Skin of regimental badge area"], correct:2, explanation:"The axillary nerve supplies deltoid, teres minor, and the skin over the lower deltoid ('regimental badge area'). Teres major is supplied by the lower subscapular nerve (C5,C6). This is clinically relevant in surgical neck fractures causing deltoid paralysis.", difficulty:"medium"},
  { id:"ana_2", text:"A patient cannot abduct the arm beyond 15 degrees after a shoulder dislocation. Which nerve is most likely injured?", options:["Radial nerve","Musculocutaneous nerve","Axillary nerve","Suprascapular nerve"], correct:2, explanation:"The axillary nerve supplies deltoid (main abductor 15°-90°). Suprascapular nerve supplies supraspinatus (first 15°). Loss of abduction beyond 15° indicates axillary nerve injury, classically seen with anterior shoulder dislocation or surgical neck fracture.", difficulty:"medium"},
  { id:"ana_3", text:"Which of the following structures passes THROUGH the carpal tunnel?", options:["Ulnar nerve","Flexor carpi radialis tendon","Palmaris longus tendon","Median nerve"], correct:3, explanation:"The carpal tunnel contains: median nerve, flexor digitorum superficialis (4 tendons), flexor digitorum profundus (4 tendons), and flexor pollicis longus tendon. The ulnar nerve passes through Guyon's canal (ulnar tunnel). Palmaris longus and FCR pass superficial to the flexor retinaculum.", difficulty:"easy"},
  { id:"ana_4", text:"Erb's palsy results from injury to which roots of the brachial plexus?", options:["C8, T1","C7, C8","C5, C6","C6, C7"], correct:2, explanation:"Erb's palsy (Erb-Duchenne palsy) results from injury to C5,C6 roots - typically from forceful separation of head and shoulder (obstetric delivery, motorcycle accidents). The arm hangs in 'waiter's tip' position: adducted, medially rotated, elbow extended, forearm pronated. C8,T1 injury causes Klumpke's palsy.", difficulty:"easy"},
  { id:"ana_5", text:"The 'anatomical snuffbox' is bounded anteriorly by which tendon?", options:["Extensor pollicis longus","Extensor pollicis brevis","Abductor pollicis longus","Flexor pollicis longus"], correct:1, explanation:"The anatomical snuffbox: anterior (radial) boundary = tendons of abductor pollicis longus and extensor pollicis brevis; posterior (ulnar) boundary = extensor pollicis longus. The floor contains the scaphoid and radial artery. Tenderness in the snuffbox suggests scaphoid fracture.", difficulty:"medium"},
  { id:"ana_6", text:"Which muscle is responsible for supination of the forearm when the elbow is extended?", options:["Biceps brachii","Supinator","Brachioradialis","Pronator teres"], correct:1, explanation:"Supinator (supplied by posterior interosseous nerve, C6) supinates regardless of elbow position. Biceps brachii is the most powerful supinator when the elbow is flexed (at 90°). With elbow extended, supinator is the primary supinator as biceps loses mechanical advantage.", difficulty:"hard"},
  { id:"ana_7", text:"A 'claw hand' deformity is most pronounced in which fingers following ulnar nerve injury at the wrist?", options:["Index and middle fingers","Thumb and index finger","Ring and little fingers","All four fingers equally"], correct:2, explanation:"Ulnar nerve palsy at the wrist causes claw hand most marked in the ring and little (4th and 5th) fingers because the lumbricals of these fingers (supplied by ulnar nerve) are paralyzed. The index and middle finger lumbricals are supplied by the median nerve, partially compensating. This is the 'ulnar paradox' - wrist injury causes more claw than elbow injury.", difficulty:"hard"},
  { id:"ana_8", text:"The brachial artery bifurcates into radial and ulnar arteries at which level?", options:["Neck of radius","Medial epicondyle of humerus","Neck of ulna","Cubital fossa, at the neck of the radius"], correct:3, explanation:"The brachial artery divides into radial and ulnar arteries at the apex/lower part of the cubital fossa, approximately at the level of the neck of the radius. This is clinically important for blood pressure measurement and arterial access. The cubital fossa boundaries: laterally brachioradialis, medially pronator teres, roof by bicipital aponeurosis.", difficulty:"medium"},
  { id:"ana_9", text:"Which rotator cuff muscle is most commonly torn?", options:["Subscapularis","Infraspinatus","Supraspinatus","Teres minor"], correct:2, explanation:"Supraspinatus is the most commonly torn rotator cuff muscle (>90% of rotator cuff tears). It is vulnerable due to its position under the coracoacromial arch and its poor blood supply at the 'critical zone' (~1cm from its insertion. Tears cause painful arc syndrome (60°-120° abduction) and inability to initiate abduction.", difficulty:"easy"},
  { id:"ana_10", text:"The median nerve enters the palm through the carpal tunnel and supplies all EXCEPT:", options:["Opponens pollicis","Abductor pollicis brevis","Flexor pollicis brevis (superficial head)","Adductor pollicis"], correct:3, explanation:"The median nerve (recurrent branch) supplies the LOAF muscles in the hand: Lumbricals (1st and 2nd), Opponens pollicis, Abductor pollicis brevis, Flexor pollicis brevis (superficial head). Adductor pollicis is supplied by the ulnar nerve. Loss of adductor pollicis causes Froment's sign.", difficulty:"medium"},
  { id:"ana_11", text:"A patient presents with foot drop after a fibular neck fracture. Which nerve is injured?", options:["Tibial nerve","Common fibular (peroneal) nerve","Superficial fibular nerve","Deep fibular nerve"], correct:1, explanation:"The common fibular (peroneal) nerve winds around the neck of the fibula, making it extremely vulnerable to injury here. It divides into superficial fibular (eversion) and deep fibular (dorsiflexion) nerves. Injury causes foot drop (inability to dorsiflex) and loss of eversion, with sensory loss over dorsum of foot.", difficulty:"easy"},
  { id:"ana_12", text:"The femoral triangle is bounded by which of the following?", options:["Sartorius laterally, adductor longus medially, inguinal ligament superiorly","Sartorius medially, adductor longus laterally, femoral ligament superiorly","Gracilis medially, rectus femoris laterally, inguinal ligament superiorly","Adductor magnus medially, vastus medialis laterally, inguinal ligament superiorly"], correct:0, explanation:"Femoral triangle boundaries: superiorly - inguinal ligament; laterally - sartorius; medially - adductor longus; floor - iliopsoas and pectineus; roof - fascia lata and cribriform fascia. Contents (lateral to medial): Nerve, Artery, Vein, Empty space, Lymphatics (NAVEL).", difficulty:"easy"},
  { id:"ana_13", text:"Which ligament prevents anterior displacement of the tibia on the femur?", options:["Posterior cruciate ligament","Medial collateral ligament","Anterior cruciate ligament","Lateral collateral ligament"], correct:2, explanation:"The anterior cruciate ligament (ACL) prevents anterior displacement of the tibia on femur and is tested by the anterior drawer test and Lachman test. The PCL prevents posterior displacement. ACL tears are common in sports with sudden deceleration/rotation. ACL attaches to anterior intercondylar area of tibia and lateral femoral condyle.", difficulty:"easy"},
  { id:"ana_14", text:"A patient has loss of sensation on the medial side of the foot. Which nerve root is involved?", options:["L4","L5","S1","S2"], correct:0, explanation:"L4 dermatome covers the medial aspect of the leg and foot (medial malleolus area). L5 covers the dorsum of foot and first web space. S1 covers the lateral foot and sole. S2 covers the posterior thigh and leg. The saphenous nerve (terminal branch of femoral nerve, L3-L4) supplies medial foot skin.", difficulty:"medium"},
  { id:"ana_15", text:"The sciatic nerve divides into tibial and common fibular nerves at which level in most individuals?", options:["At the greater sciatic foramen","At the midpoint of the back of the thigh","At the apex of the popliteal fossa","At the lower third of the thigh"], correct:2, explanation:"In most individuals, the sciatic nerve divides into tibial and common fibular nerves at the apex of the popliteal fossa. However, it may divide higher - even in the gluteal region - in some individuals. In rare cases (~12%), the common fibular nerve passes through piriformis rather than below it (causing piriformis syndrome).", difficulty:"medium"},
  { id:"ana_16", text:"Which of the following muscles is NOT in the posterior compartment of the thigh?", options:["Biceps femoris","Semimembranosus","Semitendinosus","Gracilis"], correct:3, explanation:"The posterior thigh (hamstring) compartment contains biceps femoris (long and short head), semimembranosus, and semitendinosus. Gracilis is in the medial compartment of the thigh. The hamstrings (except short head of biceps femoris) are supplied by the tibial part of the sciatic nerve and act as hip extensors and knee flexors.", difficulty:"easy"},
  { id:"ana_17", text:"During hip replacement surgery, which nerve is at greatest risk of injury in the posterior approach?", options:["Femoral nerve","Obturator nerve","Sciatic nerve","Superior gluteal nerve"], correct:2, explanation:"The sciatic nerve exits the pelvis through the greater sciatic foramen below piriformis and runs posterior to the hip joint, making it vulnerable in posterior hip replacement approach. Injury causes foot drop and loss of knee flexion. The superior gluteal nerve is at risk in the lateral approach (causing Trendelenburg gait).", difficulty:"medium"},
  { id:"ana_18", text:"Which of the following veins drains directly into the popliteal vein?", options:["Great saphenous vein","Small saphenous vein","Femoral vein","Anterior tibial vein"], correct:1, explanation:"The small (short) saphenous vein drains into the popliteal vein at the popliteal fossa, typically at the level of the knee joint. The great saphenous vein drains into the femoral vein at the saphenofemoral junction (4cm below and lateral to the pubic tubercle). This anatomy is important in varicose vein surgery.", difficulty:"medium"},
  { id:"ana_19", text:"A patient presents with inability to extend the knee and absent knee jerk. Which nerve root is most likely affected?", options:["L2, L3","L3, L4","L4, L5","L5, S1"], correct:1, explanation:"The knee jerk (patellar reflex) is L3,L4. Quadriceps (knee extension) is supplied by the femoral nerve (L2,L3,L4). Absent knee jerk with quadriceps weakness suggests L3-L4 pathology. L4 is the predominant root for the knee jerk. Ankle jerk (Achilles) tests S1.", difficulty:"easy"},
  { id:"ana_20", text:"The 'unhappy triad' (O'Donoghue's triad) of knee injuries involves which structures?", options:["ACL, PCL, medial meniscus","ACL, medial collateral ligament, medial meniscus","PCL, lateral collateral ligament, lateral meniscus","ACL, lateral collateral ligament, lateral meniscus"], correct:1, explanation:"O'Donoghue's unhappy triad involves the ACL, medial collateral ligament (MCL), and medial meniscus - all injured together by a valgus stress with external rotation (e.g., football tackle from the side). The medial meniscus is more vulnerable because it's attached to the MCL, unlike the lateral meniscus which is more mobile.", difficulty:"medium"},
  { id:"ana_21", text:"Which structure forms the posterior wall of the pericardial sac?", options:["Fibrous pericardium","Right atrium","Left atrium","Esophagus"], correct:2, explanation:"The left atrium forms the posterior wall of the heart and lies directly anterior to the esophagus. The oblique pericardial sinus lies posterior to the left atrium. An enlarged left atrium (e.g., mitral stenosis) can compress the esophagus causing dysphagia. On chest X-ray, left atrial enlargement causes a 'double shadow' and elevation of the left main bronchus.", difficulty:"medium"},
  { id:"ana_22", text:"The right coronary artery supplies the SA node in what percentage of individuals?", options:["40%","55%","60%","70%"], correct:3, explanation:"The SA node artery arises from the RCA in ~60-70% of individuals and from the LCx in ~30-40%. The AV node artery arises from the dominant coronary artery - in right dominant circulation (~85%), it comes from RCA. This explains why inferior MI (RCA territory) often causes SA node dysfunction and heart block.", difficulty:"hard"},
  { id:"ana_23", text:"A patient with lung cancer has hoarseness of voice. The tumor is most likely located at which site?", options:["Right upper lobe","Left upper lobe","Right lower lobe","Right middle lobe"], correct:1, explanation:"The left recurrent laryngeal nerve loops under the arch of the aorta and ligamentum arteriosum at the hilum, making it vulnerable to compression by left upper lobe tumors or mediastinal lymph nodes. The right recurrent laryngeal nerve loops under the right subclavian artery at a higher level. Hoarseness with lung cancer = left-sided pathology.", difficulty:"medium"},
  { id:"ana_24", text:"The pleural cavity extends below the costal margin in which two regions?", options:["Epigastric and right hypochondriac","Right and left hypochondriac","Right hypochondriac and lumbar","Epigastric and left hypochondriac"], correct:1, explanation:"The pleural cavity extends below the costal margin in the right and left hypochondriac regions (costodiaphragmatic recesses). This is important in procedures like kidney surgery - the pleural cavity may be inadvertently entered. The lung does not fill these recesses during normal breathing; they serve as reserve space during deep inspiration.", difficulty:"hard"},
  { id:"ana_25", text:"Which of the following is the CORRECT sequence of the pericardial sinuses?", options:["Transverse sinus lies anterior to aorta and pulmonary trunk","Oblique sinus lies between the four pulmonary veins and venae cavae","Transverse sinus separates arterial (aorta/PA) from venous structures","Both B and C are correct"], correct:3, explanation:"The transverse pericardial sinus is a passage posterior to the ascending aorta and pulmonary trunk, and anterior to the SVC and left atrium. The oblique pericardial sinus is bounded by the four pulmonary veins laterally, the IVC inferiorly, and the left atrium posteriorly. Both B and C describe these sinuses correctly.", difficulty:"hard"},
  { id:"ana_26", text:"Which part of the diaphragm is pierced by the esophagus?", options:["Central tendon","Right crus at T8","Right crus at T10","Sternal part"], correct:2, explanation:"Three major diaphragm openings: T8 - caval opening in central tendon (IVC + right phrenic nerve); T10 - esophageal hiatus in right crus (esophagus + vagus nerves); T12 - aortic hiatus behind the diaphragm (aorta + thoracic duct + azygos vein). Mnemonic: 'I 8 (ate) 10 eggs at 12 (noon)'.", difficulty:"easy"},
  { id:"ana_27", text:"During appendectomy, which nerve may be identified in the mesoappendix?", options:["Ilioinguinal nerve","Iliohypogastric nerve","Ilioinguinal and genitofemoral nerve","None - no named nerve runs through mesoappendix"], correct:3, explanation:"No named nerve runs through the mesoappendix. The appendicular artery (branch of ileocolic artery) runs in the mesoappendix. The ilioinguinal and iliohypogastric nerves run in the abdominal wall anterior to the peritoneum and are at risk during incisions for appendectomy (McBurney's or Lanz incision).", difficulty:"hard"},
  { id:"ana_28", text:"The portal vein is formed by the union of which vessels behind the neck of the pancreas?", options:["Superior mesenteric vein and inferior mesenteric vein","Superior mesenteric vein and splenic vein","Inferior mesenteric vein and splenic vein","Superior mesenteric vein, inferior mesenteric vein, and splenic vein"], correct:1, explanation:"The portal vein is formed by the union of the superior mesenteric vein (SMV) and splenic vein behind the neck of the pancreas at the level of L2. The inferior mesenteric vein (IMV) usually drains into the splenic vein (sometimes into SMV or the junction). The portal vein ascends in the free edge of the lesser omentum (hepatoduodenal ligament).", difficulty:"easy"},
  { id:"ana_29", text:"McBurney's point, the site of maximum tenderness in acute appendicitis, is located:", options:["At the umbilicus","1/3 of the way from the right anterior superior iliac spine to the umbilicus","1/3 of the way from the umbilicus to the right ASIS","2/3 of the way from the umbilicus to the right ASIS"], correct:2, explanation:"McBurney's point is located 1/3 of the way from the right anterior superior iliac spine (ASIS) to the umbilicus (i.e., 2/3 of the way from the umbilicus to the right ASIS). The appendix base is relatively constant at this point. McBurney's incision is made perpendicular to this line.", difficulty:"easy"},
  { id:"ana_30", text:"Which of the following structures is NOT a content of the inguinal canal in males?", options:["Vas deferens","Testicular artery","Genital branch of genitofemoral nerve","Ilioinguinal nerve"], correct:3, explanation:"The inguinal canal in males contains: vas deferens, testicular artery, pampiniform plexus, testicular lymphatics, ilioinguinal nerve (runs in the canal but enters through the deep ring separately), genital branch of genitofemoral nerve, cremaster muscle (from internal oblique). The ilioinguinal nerve enters the canal through the superficial ring, NOT the deep ring.", difficulty:"hard"},
  { id:"ana_31", text:"A direct inguinal hernia passes:", options:["Through the deep inguinal ring only","Through both deep and superficial inguinal rings","Through the superficial ring only","Through Hesselbach's triangle and then the superficial ring"], correct:3, explanation:"A direct inguinal hernia pushes directly through the posterior wall of the inguinal canal (Hesselbach's triangle) and exits through the superficial inguinal ring. It does NOT pass through the deep ring. Hesselbach's triangle: medially by the rectus abdominis, laterally by the inferior epigastric vessels, inferiorly by the inguinal ligament.", difficulty:"medium"},
  { id:"ana_32", text:"The liver receives its blood supply from which sources?", options:["Only hepatic artery proper","Only portal vein","Hepatic artery (25%) and portal vein (75%)","Portal vein (25%) and hepatic artery (75%)"], correct:2, explanation:"The liver has dual blood supply: portal vein (75% of volume, 50% of oxygen) and hepatic artery (25% of volume, 50% of oxygen). The hepatic artery proper is a branch of the common hepatic artery from the celiac trunk. Portal blood is nutrient-rich (from GI tract and spleen). Both contribute equally to hepatic oxygenation.", difficulty:"easy"},
  { id:"ana_33", text:"The pelvic floor is primarily formed by which muscle?", options:["Coccygeus","Levator ani","Piriformis","Obturator internus"], correct:1, explanation:"The pelvic diaphragm is formed primarily by levator ani (which has three parts: pubococcygeus, iliococcygeus, and puborectalis) and the coccygeus muscle. Levator ani forms the majority. It supports pelvic viscera, resists increased intra-abdominal pressure, and has important roles in micturition, defecation, and parturition.", difficulty:"easy"},
  { id:"ana_34", text:"Which nerve supplies the external urethral sphincter?", options:["Pudendal nerve (S2,S3,S4)","Pelvic splanchnic nerves","Hypogastric nerve","Inferior hypogastric plexus"], correct:0, explanation:"The external urethral sphincter (voluntary) is supplied by the pudendal nerve (S2,S3,S4) via the perineal branch. The internal urethral sphincter (involuntary) is under sympathetic control (hypogastric nerve, L1,L2). Pelvic splanchnic nerves (parasympathetic, S2-S4) cause detrusor contraction and bladder emptying.", difficulty:"medium"},
  { id:"ana_35", text:"The ureter crosses the pelvic brim at which vessel?", options:["External iliac artery","Common iliac artery bifurcation","Internal iliac artery","Uterine artery"], correct:1, explanation:"The ureter crosses the pelvic brim (bifurcation of common iliac artery) to enter the pelvis. In males, the vas deferens crosses over the ureter near the bladder. In females, the uterine artery crosses over the ureter ('water under the bridge') - a critical surgical landmark during hysterectomy to avoid ureteral injury.", difficulty:"medium"},
  { id:"ana_36", text:"Which cranial nerve is tested by the 'jaw jerk' reflex?", options:["CN V1 (ophthalmic)","CN V2 (maxillary)","CN V3 (mandibular)","CN VII (facial)"], correct:2, explanation:"The jaw jerk is a monosynaptic stretch reflex testing CN V3 (mandibular division of trigeminal nerve). The afferent and efferent are both CN V3 (mesencephalic nucleus for afferent, motor nucleus for efferent). It is exaggerated in pseudobulbar palsy (UMN lesion) and absent/reduced in bulbar palsy (LMN lesion).", difficulty:"medium"},
  { id:"ana_37", text:"A patient presents with inability to close the eye, loss of taste from anterior 2/3 of tongue, and hyperacusis. Where is the lesion?", options:["At the stylomastoid foramen","In the parotid gland","In the internal auditory meatus","Proximal to the nerve to stapedius but distal to the geniculate ganglion"], correct:3, explanation:"Facial nerve lesion proximal to the nerve to stapedius (which prevents hyperacusis) but distal to the geniculate ganglion: features are LMN facial palsy + taste loss (chorda tympani) + hyperacusis (stapedius paralysis) but NO loss of lacrimation (greater petrosal nerve is spared at geniculate ganglion level). This localizes to the facial canal below the geniculate ganglion.", difficulty:"hard"},
  { id:"ana_38", text:"The thyroid gland is derived embryologically from:", options:["First pharyngeal pouch","Third pharyngeal pouch","Foramen cecum at the junction of anterior 2/3 and posterior 1/3 of tongue","Second branchial arch"], correct:2, explanation:"The thyroid gland develops from a downgrowth of endoderm at the foramen cecum (junction of anterior 2/3 and posterior 1/3 of the tongue) and descends in the neck. The thyroglossal duct marks this descent. Remnants form thyroglossal duct cysts (midline neck swellings that move up on tongue protrusion). The parafollicular C-cells come from neural crest via 4th pharyngeal pouch.", difficulty:"medium"},
  { id:"ana_39", text:"The parotid gland is traversed by which nerve?", options:["Lingual nerve","Hypoglossal nerve","Facial nerve","Auriculotemporal nerve"], correct:2, explanation:"The facial nerve (CN VII) passes through the parotid gland, dividing it into superficial and deep lobes. It divides into five terminal branches: temporal, zygomatic, buccal, marginal mandibular, and cervical. This is crucial during parotid surgery - the facial nerve must be identified and preserved. Parotid tumors can cause facial nerve palsy.", difficulty:"easy"},
  { id:"ana_40", text:"Horner's syndrome consists of all the following EXCEPT:", options:["Ptosis","Miosis","Anhidrosis of the face","Exophthalmos"], correct:3, explanation:"Horner's syndrome = sympathetic chain interruption: ptosis (superior tarsal muscle, Müller's muscle), miosis (dilator pupillae paralyzed), anhidrosis (loss of facial sweating), and enophthalmos (apparent, not true). Exophthalmos (proptosis) is the OPPOSITE - it occurs in hyperthyroidism and Graves' disease. Horner's is caused by Pancoast tumor, carotid dissection, syringomyelia, etc.", difficulty:"easy"},
  { id:"ana_41", text:"The optic chiasm lies directly above which structure, making it susceptible to compression by pituitary tumors?", options:["Sphenoidal sinus","Diaphragma sellae","Cavernous sinus","Pituitary gland (sella turcica)"], correct:3, explanation:"The optic chiasm lies directly above the pituitary gland in the sella turcica. A pituitary adenoma growing upward compresses the crossing nasal fibers of the optic chiasm, causing bitemporal hemianopia (loss of both temporal fields). This is the classic 'tunnel vision' or 'blinker vision' presentation of pituitary macroadenoma.", difficulty:"easy"},
  { id:"ana_42", text:"Which sinus drains into the middle meatus of the nasal cavity?", options:["Sphenoidal sinus","Posterior ethmoidal sinus","Frontal sinus","Nasolacrimal duct"], correct:2, explanation:"Middle meatus drainage: frontal sinus (via frontonasal duct/infundibulum), maxillary sinus (via hiatus semilunaris), and anterior ethmoidal cells. Superior meatus: posterior ethmoidal cells. Sphenoidal sinus drains into sphenoethmoidal recess (above superior concha). Nasolacrimal duct drains into inferior meatus.", difficulty:"medium"},
  { id:"ana_43", text:"Which cranial nerve carries the afferent limb of the gag reflex?", options:["CN IX alone","CN X alone","CN IX (afferent) and CN X (efferent)","CN V3 (afferent) and CN IX (efferent)"], correct:2, explanation:"The gag reflex: afferent = glossopharyngeal nerve (CN IX) from the posterior pharynx; efferent = vagus nerve (CN X) causing pharyngeal muscle contraction. CN IX also carries taste from the posterior 1/3 of the tongue. Testing the gag reflex helps assess posterior fossa lesions and CN IX/X function.", difficulty:"easy"},
  { id:"ana_44", text:"A stab wound to the posterior triangle of the neck injures which nerve, causing winged scapula?", options:["Dorsal scapular nerve","Long thoracic nerve","Spinal accessory nerve","Thoracodorsal nerve"], correct:1, explanation:"The long thoracic nerve (C5,C6,C7) runs on the superficial surface of serratus anterior and is vulnerable in the posterior triangle. Injury causes 'winged scapula' (medial border of scapula protrudes) because serratus anterior normally holds the scapula against the chest wall. Tested by asking patient to push against a wall.", difficulty:"medium"},
  { id:"ana_45", text:"Which of the following correctly describes the carotid sinus?", options:["It is a dilatation of the external carotid artery","It contains chemoreceptors sensitive to hypoxia","It is located at the bifurcation of the common carotid artery","It is innervated by the vagus nerve"], correct:2, explanation:"The carotid sinus is a baroreceptor (pressure-sensitive) dilatation at the bifurcation of the common carotid artery (or base of internal carotid). It is innervated by the carotid sinus nerve (Hering's nerve), a branch of CN IX. The carotid body (nearby) is the chemoreceptor sensitive to hypoxia, hypercapnia, acidosis.", difficulty:"medium"},
  { id:"ana_46", text:"The vertebral artery passes through the transverse foramina of which vertebrae?", options:["C1 through C7","C2 through C6","C1 through C6","C2 through C7"], correct:2, explanation:"The vertebral artery enters the transverse foramen of C6 and ascends through C6-C1 (all cervical vertebrae except C7). It then loops around the posterior arch of C1 (atlas) and enters the foramen magnum to form the basilar artery by uniting with its counterpart. C7 has a transverse foramen but the vertebral artery does not pass through it.", difficulty:"medium"},
  { id:"ana_47", text:"The spinal cord ends at which vertebral level in adults?", options:["L1-L2","L3-L4","T12-L1","L2-L3"], correct:0, explanation:"In adults, the spinal cord (conus medullaris) ends at L1-L2. In neonates, it ends at L3. Below the conus, nerve roots form the cauda equina ('horse's tail'). Lumbar puncture is performed at L3-L4 or L4-L5 (below the conus) to avoid cord injury. The filum terminale anchors the cord to the coccyx.", difficulty:"easy"},
  { id:"ana_48", text:"Which dermatome corresponds to the umbilicus?", options:["T8","T10","T12","L1"], correct:1, explanation:"The umbilicus corresponds to the T10 dermatome. Key landmarks: T4 = nipple line; T6 = xiphisternum; T10 = umbilicus; T12/L1 = groin/inguinal region. This is tested by the abdominal reflex. In early appendicitis, pain begins periumbilically (T10 referred pain from the appendix, which shares T10 innervation) before localizing to the right iliac fossa.", difficulty:"easy"},
  { id:"ana_49", text:"Which intervertebral disc herniation most commonly affects the L5 nerve root?", options:["L3/L4 disc herniation","L4/L5 disc herniation","L5/S1 disc herniation","L2/L3 disc herniation"], correct:1, explanation:"In disc herniation, the disc compresses the nerve root that exits at the LOWER level: L4/L5 disc compresses L5 root (causing weakness of dorsiflexion, loss of sensation in first web space, absent no ankle jerk). L5/S1 disc compresses S1 root (absent ankle jerk, weakness of plantar flexion, lateral foot numbness). L4/L5 is the most common disc herniation.", difficulty:"medium"},
  { id:"ana_50", text:"The epidural space contains all of the following EXCEPT:", options:["Fat","Internal vertebral venous plexus","Spinal cord","Nerve roots"], correct:2, explanation:"The epidural space lies between the dura mater and the periosteum of the vertebral canal. It contains: epidural fat, internal vertebral venous plexus (Batson's plexus), lymphatics, small arteries, and nerve roots as they exit. The spinal cord itself is within the subarachnoid space, covered by pia mater. Epidural anesthesia targets this space.", difficulty:"medium"},
  { id:"ana_51", text:"The Circle of Willis is MOST commonly incomplete at which part?", options:["Anterior communicating artery","Posterior communicating artery","Basilar artery","Anterior cerebral artery A1 segment"], correct:1, explanation:"The Circle of Willis is most commonly incomplete at the posterior communicating arteries - they are absent or hypoplastic in ~25-30% of individuals. This is the most common variation. The anterior communicating artery is present in most individuals. Aneurysms most commonly occur at the anterior communicating artery and the junction of the ICA and PCA.", difficulty:"hard"},
  { id:"ana_52", text:"Which artery is the most common site of hypertensive intracerebral hemorrhage?", options:["Middle cerebral artery","Anterior cerebral artery","Lenticulostriate arteries","Posterior cerebral artery"], correct:2, explanation:"Lenticulostriate arteries (branches of middle cerebral artery) are the most common site of hypertensive hemorrhage - they are called 'arteries of stroke' (Charcot). They supply the basal ganglia and internal capsule. Rupture causes contralateral hemiplegia. These small perforating arteries are particularly vulnerable to hypertension-induced lipohyalinosis.", difficulty:"medium"},
  { id:"ana_53", text:"A lesion of the right optic tract causes which visual field defect?", options:["Right homonymous hemianopia","Left homonymous hemianopia","Right nasal hemianopia","Bitemporal hemianopia"], correct:1, explanation:"The right optic tract carries fibers from the nasal retina of the LEFT eye and the temporal retina of the RIGHT eye - both representing the LEFT visual field. A right optic tract lesion causes LEFT homonymous hemianopia. A left optic tract lesion causes right homonymous hemianopia. Tract lesions are characterized by incongruous field defects.", difficulty:"medium"},
  { id:"ana_54", text:"Which part of the cerebellum is primarily responsible for coordination of limb movements?", options:["Flocculonodular lobe (archicerebellum)","Vermis (spinocerebellum - medial zone)","Hemisphere (neocerebellum/cerebrocerebellum)","Anterior lobe only"], correct:2, explanation:"The cerebellar hemispheres (neocerebellum/cerebrocerebellum) coordinate limb movements via the dentate nucleus and connections with the motor cortex. The flocculonodular lobe coordinates eye movements and balance (damaged in midline tumors causing gait ataxia). The vermis coordinates trunk and gait. Hemisphere lesions cause ipsilateral limb ataxia, intention tremor, and dysdiadochokinesia.", difficulty:"medium"},
  { id:"ana_55", text:"The substantia nigra projects dopaminergic fibers to which structure via the nigrostriatal pathway?", options:["Globus pallidus","Caudate nucleus and putamen (striatum)","Thalamus","Subthalamic nucleus"], correct:1, explanation:"The nigrostriatal pathway: substantia nigra pars compacta → striatum (caudate nucleus + putamen). Dopamine is inhibitory on the indirect pathway and excitatory on the direct pathway, overall facilitating movement. Degeneration of this pathway causes Parkinson's disease (tremor, rigidity, bradykinesia). The caudate and putamen together = striatum = 'neostriatum'.", difficulty:"medium"},
  { id:"ana_56", text:"The internal capsule's posterior limb carries which important fiber tracts?", options:["Corticobulbar fibers only","Thalamocortical sensory fibers only","Corticospinal fibers and thalamocortical (sensory) fibers","Frontopontine fibers only"], correct:2, explanation:"The posterior limb of the internal capsule carries: corticospinal tract (motor fibers), corticobulbar fibers (to brainstem motor nuclei), and thalamocortical somatosensory fibers. The anterior limb contains frontopontine and anterior thalamic radiations. The genu contains corticobulbar fibers. Internal capsule stroke causes contralateral hemiplegia and hemisensory loss.", difficulty:"hard"},
  { id:"ana_57", text:"Simple squamous epithelium is found in which of the following locations?", options:["Tracheal lining","Urinary bladder","Alveolar walls (type I pneumocytes)","Cervical canal"], correct:2, explanation:"Simple squamous epithelium lines: alveoli (type I pneumocytes), Bowman's capsule parietal layer, loop of Henle thin segment, blood vessels (endothelium), lymphatics, heart (mesothelium), and pleural/pericardial/peritoneal surfaces. The trachea is lined by pseudostratified ciliated columnar epithelium. Bladder = transitional (urothelium). Cervical canal = simple columnar.", difficulty:"easy"},
  { id:"ana_58", text:"Which type of cartilage is found in the intervertebral discs?", options:["Hyaline cartilage","Elastic cartilage","Fibrocartilage","No cartilage - it is fibrous tissue"], correct:2, explanation:"The annulus fibrosus of intervertebral discs is composed of fibrocartilage (collagen type I and some type II). Fibrocartilage also occurs in the pubic symphysis, menisci, and temporomandibular joint disc. Hyaline cartilage lines articular surfaces. Elastic cartilage is in the epiglottis, external ear, and Eustachian tube.", difficulty:"easy"},
  { id:"ana_59", text:"The Haversian system (osteon) is a feature of which type of bone?", options:["Woven bone","Cancellous (trabecular) bone","Compact (cortical) bone","Both woven and lamellar bone"], correct:2, explanation:"Haversian systems (osteons) are the structural unit of compact cortical bone. Each osteon consists of concentric lamellae surrounding a central Haversian canal containing blood vessels and nerves. Volkmann's canals run transversely connecting Haversian canals. Cancellous bone has trabeculae arranged along lines of stress without Haversian systems.", difficulty:"easy"},
  { id:"ana_60", text:"Megakaryocytes are found in which organ and give rise to which cellular elements?", options:["Spleen, giving rise to red blood cells","Bone marrow, giving rise to platelets","Liver, giving rise to white blood cells","Lymph nodes, giving rise to lymphocytes"], correct:1, explanation:"Megakaryocytes are large polyploid cells in the bone marrow that shed their cytoplasm as platelets (thrombocytes). One megakaryocyte produces ~2000-3000 platelets. They are stimulated by thrombopoietin (TPO) produced by the liver. Platelet count: 150,000-400,000/μL; lifespan 8-10 days.", difficulty:"easy"},
  { id:"ana_61", text:"The notochord induces formation of which structure?", options:["Neural plate only","Somites only","Neural plate (and thus the neural tube)","Lateral plate mesoderm"], correct:2, explanation:"The notochord (derived from mesoderm) induces the overlying ectoderm to form the neural plate, which subsequently folds to form the neural tube (neurulation, day 18-28). The notochord itself eventually becomes the nucleus pulposus of the intervertebral disc. Failure of neural tube closure causes neural tube defects (spina bifida, anencephaly).", difficulty:"medium"},
  { id:"ana_62", text:"The neural crest cells give rise to all of the following EXCEPT:", options:["Dorsal root ganglion neurons","Adrenal medulla chromaffin cells","Melanocytes","Skeletal muscle"], correct:3, explanation:"Neural crest cells are pluripotent migratory cells that form: peripheral nervous system (dorsal root ganglia, autonomic ganglia), adrenal medulla, melanocytes, facial bones and cartilage, odontoblasts, Schwann cells, meninges (cranial). Skeletal muscle is derived from paraxial mesoderm (somites - myotome).", difficulty:"medium"},
  { id:"ana_63", text:"At what stage of development does implantation of the blastocyst occur?", options:["Day 2-3 (morula stage)","Day 6-7 (blastocyst stage)","Day 14 (gastrulation stage)","Day 28 (somite stage)"], correct:1, explanation:"Implantation occurs at day 6-7 when the blastocyst (containing inner cell mass/embryoblast and outer trophoblast) adheres to and invades the uterine endometrium (secretory phase). The trophoblast differentiates into cytotrophoblast and syncytiotrophoblast. hCG is secreted by the syncytiotrophoblast from day 8, maintaining the corpus luteum.", difficulty:"easy"},
  { id:"ana_64", text:"The tetralogy of Fallot results from which embryological defect?", options:["Anterior displacement of the infundibular septum","Posterior displacement of the infundibular septum","Failure of AV septum to close","Failure of foramen ovale to close"], correct:0, explanation:"Tetralogy of Fallot results from anterior and superior displacement of the infundibular (conal) septum, causing: (1) pulmonary stenosis, (2) overriding aorta, (3) VSD, (4) right ventricular hypertrophy. It is the most common cyanotic congenital heart disease after age 1. Presents with 'Tet spells' and boot-shaped heart on CXR.", difficulty:"medium"},
  { id:"ana_65", text:"The lateral pterygoid muscle is responsible for which jaw movement?", options:["Elevation of the mandible","Depression of the mandible (with suprahyoid muscles)","Protrusion and lateral deviation of the mandible","Retraction of the mandible"], correct:2, explanation:"Lateral pterygoid: protrudes mandible (both sides together) and deviates to opposite side (one side). It is the only muscle of mastication active during mouth OPENING (along with suprahyoid muscles and gravity). Medial pterygoid, masseter, and temporalis are ELEVATORS (mouth closing). Temporalis also retracts the mandible (posterior fibers).", difficulty:"medium"},
  { id:"ana_66", text:"Which ligament connects the two pubic bones at the pubic symphysis?", options:["Inguinal ligament","Superior pubic ligament","Iliolumbar ligament","Arcuate pubic ligament"], correct:3, explanation:"The pubic symphysis is a secondary cartilaginous joint (symphysis). Its ligaments: superior pubic ligament, arcuate (inferior) pubic ligament (strongest), anterior pubic ligament, and posterior ligament. The interpubic disc of fibrocartilage is between the bones. The joint widens during pregnancy under relaxin influence.", difficulty:"medium"},
  { id:"ana_67", text:"The Wormian bones (intrasutural bones) are most characteristically seen in which condition?", options:["Achondroplasia","Osteogenesis imperfecta","Rickets","Osteoporosis"], correct:1, explanation:"Wormian bones (accessory ossicles within skull sutures) are characteristic of osteogenesis imperfecta (due to type I collagen defect). Also seen in: cleidocranial dysostosis, hypothyroidism, Down syndrome, and rickets. In osteogenesis imperfecta: blue sclerae, brittle bones, dental abnormalities, and hearing loss also occur.", difficulty:"medium"},
  { id:"ana_68", text:"The thoracic duct begins at the cisterna chyli at which vertebral level?", options:["T6","T8","L1","L2"], correct:2, explanation:"The cisterna chyli (receptaculum chyli) is a lymphatic sac at L1-L2, formed by the union of right and left lumbar lymphatic trunks and the intestinal trunk. The thoracic duct arises from the cisterna chyli, ascends through the aortic hiatus (T12), crosses the midline at T4-T5, and drains into the left subclavian vein at the jugulosubclavian angle.", difficulty:"medium"},
  { id:"ana_69", text:"The left recurrent laryngeal nerve supplies all laryngeal muscles EXCEPT:", options:["Cricothyroid muscle","Posterior cricoarytenoid","Lateral cricoarytenoid","Thyroarytenoid"], correct:0, explanation:"The recurrent laryngeal nerves supply ALL intrinsic laryngeal muscles EXCEPT the cricothyroid muscle (supplied by the external laryngeal nerve, branch of superior laryngeal nerve). Cricothyroid is the tensor of the vocal cord and is the only laryngeal muscle supplied by the external laryngeal nerve. RLN injury causes hoarseness and risk of aspiration.", difficulty:"medium"},
  { id:"ana_70", text:"Trendelenburg gait is caused by weakness of which muscle?", options:["Iliopsoas","Gluteus maximus","Gluteus medius and minimus","Tensor fascia lata"], correct:2, explanation:"Trendelenburg gait is caused by weakness of gluteus medius and minimus (hip abductors, supplied by superior gluteal nerve L4,L5,S1). When standing on the affected limb, the pelvis drops on the opposite side (positive Trendelenburg sign), and the trunk leans over the weak side to compensate. Caused by superior gluteal nerve injury, hip pathology, or L4/L5 lesions.", difficulty:"easy"},
  { id:"ana_71", text:"The blood-brain barrier is formed primarily by which cellular structure?", options:["Choroid plexus epithelium","Tight junctions between brain capillary endothelial cells","Astrocyte end-feet alone","Pericytes"], correct:1, explanation:"The blood-brain barrier (BBB) is primarily formed by tight junctions (zonula occludens) between brain capillary endothelial cells. Astrocyte end-feet surround the capillaries and induce and maintain BBB properties but are not the barrier itself. Pericytes also play a role. Lipid-soluble substances, O2, CO2, and glucose (via GLUT1) cross freely.", difficulty:"medium"},
  { id:"ana_72", text:"The pes anserinus is the combined tendon insertion of which muscles?", options:["Sartorius, gracilis, semitendinosus","Sartorius, gracilis, semimembranosus","Biceps femoris, semitendinosus, semimembranosus","Sartorius, adductor longus, gracilis"], correct:0, explanation:"The pes anserinus ('goose foot') is the combined insertion of sartorius, gracilis, and semitendinosus on the medial surface of the tibia below the medial condyle. Mnemonic: 'Say Grace before Tea' (Sartorius, Gracilis, Semitendinosus). Pes anserinus bursitis causes medial knee pain, often in obese patients with knee OA.", difficulty:"medium"},
  { id:"ana_73", text:"The coronary sinus opens into which cardiac chamber?", options:["Right ventricle","Left atrium","Right atrium","Left ventricle"], correct:2, explanation:"The coronary sinus opens into the right atrium between the inferior vena cava opening and the tricuspid valve (AV orifice), guarded by the valve of the coronary sinus (Thebesian valve). It receives most venous drainage from the heart via the great, middle, small cardiac veins, and oblique vein of Marshall. Some venous blood drains directly via anterior cardiac veins.", difficulty:"easy"},
  { id:"ana_74", text:"Which layer of the epidermis is responsible for cell division (mitosis)?", options:["Stratum corneum","Stratum granulosum","Stratum spinosum","Stratum basale"], correct:3, explanation:"The stratum basale (stratum germinativum) is the deepest layer containing stem cells and melanocytes. It is the only layer with significant mitotic activity. Newly formed cells push upward through spinosum → granulosum → lucidum (in thick skin) → corneum. The complete cycle from basale to corneum shedding takes ~28-40 days.", difficulty:"easy"},
  { id:"ana_75", text:"The recurrent branch of the median nerve (motor branch to thenar muscles) passes superficial to the flexor retinaculum. Injury to this branch would cause:", options:["Loss of thumb adduction","Loss of thumb opposition","Loss of thumb flexion at IP joint","Loss of thumb extension"], correct:1, explanation:"The recurrent (motor) branch of the median nerve supplies the thenar muscles: abductor pollicis brevis, flexor pollicis brevis (superficial head), and opponens pollicis. Loss of these muscles, particularly opponens pollicis, results in inability to oppose the thumb (touch thumb to little fingertip). This is 'simian hand' or ape hand deformity.", difficulty:"medium"},
  { id:"ana_76", text:"The obturator nerve (L2,L3,L4) exits the pelvis through the obturator foramen and supplies which movement primarily?", options:["Hip flexion","Hip abduction","Hip adduction","Hip extension"], correct:2, explanation:"The obturator nerve supplies the medial compartment of the thigh (hip adductors): adductor longus, adductor brevis, adductor magnus (anterior part), gracilis, and obturator externus. Hip adduction is its primary motor function. It also supplies a cutaneous branch to the medial thigh. Obturator nerve palsy causes weakness of adduction and sometimes medial thigh numbness.", difficulty:"easy"},
  { id:"ana_77", text:"The ductus arteriosus connects which two vessels in fetal circulation?", options:["Pulmonary artery to aorta","Aorta to pulmonary vein","Ductus venosus to inferior vena cava","Left atrium to right atrium"], correct:0, explanation:"The ductus arteriosus connects the pulmonary trunk (main pulmonary artery) to the aorta (distal to left subclavian artery) in fetal circulation, allowing blood to bypass the lungs. At birth, it closes with the rise in O2 tension (causing prostaglandin reduction). Persists as ligamentum arteriosum. PDA is closed by indomethacin (inhibits prostaglandins) or surgically.", difficulty:"easy"},
  { id:"ana_78", text:"The hepatoduodenal ligament (free edge of lesser omentum) contains all of the following EXCEPT:", options:["Portal vein (posterior)","Hepatic artery proper (left)","Common bile duct (right)","Inferior mesenteric artery"], correct:3, explanation:"The hepatoduodenal ligament contains the 'portal triad': portal vein (posterior), hepatic artery proper (left/anteromedial), and common bile duct (right/anterolateral). This structure forms Pringle's maneuver when compressed to control hemorrhage. The inferior mesenteric artery is NOT in this ligament - it is in the retroperitoneum.", difficulty:"medium"},
  { id:"ana_79", text:"The posterior communicating artery aneurysm classically presents with which cranial nerve palsy?", options:["CN II palsy","CN III palsy with pupil sparing","CN III palsy with pupil involvement","CN VI palsy"], correct:2, explanation:"PCA aneurysm (at the junction of ICA and PCA) classically causes CN III palsy WITH pupil involvement (mydriasis - dilated, fixed pupil) because the pupillomotor fibers travel on the outside of the nerve and are compressed first. This differentiates it from 'medical' (diabetic) CN III palsy which SPARES the pupil (ischemia affects core fibers first). Urgent neurosurgical consultation needed.", difficulty:"hard"},
  { id:"ana_80", text:"The pterion is the meeting point of which four bones?", options:["Frontal, parietal, temporal, occipital","Frontal, parietal, temporal, sphenoid","Parietal, temporal, occipital, sphenoid","Frontal, temporal, sphenoid, zygomatic"], correct:1, explanation:"The pterion is the H-shaped junction of frontal, parietal, temporal, and sphenoid bones on the lateral skull. It overlies the anterior division of the middle meningeal artery. A blow to the temple fractures the thinnest part of the skull here, tearing the artery and causing extradural (epidural) hematoma - the classic 'talk and die' lucid interval scenario.", difficulty:"medium"},
  { id:"ana_81", text:"The Sertoli cells of the testis perform which function?", options:["Produce testosterone","Produce inhibin B and support spermatogenesis","Produce luteinizing hormone","Form the blood-testis barrier exclusively"], correct:1, explanation:"Sertoli cells are nurse cells that: (1) produce inhibin B (suppresses FSH), (2) secrete androgen-binding protein (ABP) to concentrate testosterone for spermatogenesis, (3) form the blood-testis barrier via tight junctions, (4) phagocytose residual bodies, (5) produce anti-Müllerian hormone (AMH) in fetal development causing regression of Müllerian ducts. Leydig cells produce testosterone.", difficulty:"medium"},
  { id:"ana_82", text:"The lymphatic drainage of the testis follows the testicular vessels to drain into which lymph nodes?", options:["Inguinal lymph nodes","Para-aortic (lumbar) lymph nodes at L1","Iliac lymph nodes","Pelvic lymph nodes"], correct:1, explanation:"The testes develop in the retroperitoneum and descend, but their lymphatic drainage follows the testicular vessels (gonadal vessels) to para-aortic lymph nodes at L1. Therefore, testicular cancer metastasizes to para-aortic nodes (unlike scrotal skin which drains to inguinal nodes). This distinction is vital in staging and treatment of testicular tumors.", difficulty:"medium"},
  { id:"ana_83", text:"Which of the following muscles forms the floor of the cubital fossa?", options:["Brachialis and supinator","Pronator teres and brachioradialis","Biceps brachii tendon","Supinator and pronator teres"], correct:0, explanation:"The cubital fossa floor is formed by brachialis (medially) and supinator (laterally). Roof: bicipital aponeurosis and skin. Lateral border: brachioradialis. Medial border: pronator teres. Contents (lateral to medial): Radial Nerve, Biceps tendon, Brachial Artery, Median Nerve. Mnemonic: 'Really Need Beer Mugs'.", difficulty:"medium"},
  { id:"ana_84", text:"The foramen of Winslow (epiploic foramen) connects which two spaces?", options:["Greater and lesser sacs of peritoneum","Peritoneal cavity and retroperitoneum","Right subphrenic space and hepatorenal space","Supracolic and infracolic compartments"], correct:0, explanation:"The epiploic foramen (foramen of Winslow) is the communication between the greater sac (peritoneal cavity) and the lesser sac (omental bursa). Boundaries: anteriorly - hepatoduodenal ligament; posteriorly - IVC; superiorly - caudate lobe of liver; inferiorly - first part of duodenum. Fluid can collect in the lesser sac (e.g., acute pancreatitis).", difficulty:"medium"},
  { id:"ana_85", text:"Referred pain from the diaphragm is felt at the tip of the shoulder because the phrenic nerve arises from which segments?", options:["C1, C2, C3","C2, C3, C4","C3, C4, C5","C4, C5, C6"], correct:2, explanation:"The phrenic nerve (C3,C4,C5 - 'C3,4,5 keep the diaphragm alive') supplies the diaphragm. Irritation (e.g., subphrenic abscess, ruptured ectopic pregnancy, pneumoperitoneum) refers pain to the C4 dermatome - the tip of the shoulder (supraclavicular region). This is called Kehr's sign when the left shoulder is involved (e.g., splenic rupture).", difficulty:"easy"},
  { id:"ana_86", text:"The nasolacrimal duct drains tears into which part of the nasal cavity?", options:["Superior meatus","Middle meatus","Inferior meatus","Sphenoethmoidal recess"], correct:2, explanation:"The nasolacrimal duct drains into the inferior meatus of the nasal cavity (beneath the inferior nasal concha). This is why excessive tearing leads to a 'runny nose.' Blockage of the nasolacrimal duct causes epiphora (overflow of tears). The middle meatus receives drainage from the frontal, maxillary, and anterior ethmoidal sinuses.", difficulty:"easy"},
  { id:"ana_87", text:"The sternocleidomastoid muscle is supplied by which nerve?", options:["Ansa cervicalis","Accessory nerve (CN XI) and C2,C3","Facial nerve (CN VII)","Hypoglossal nerve (CN XII)"], correct:1, explanation:"The sternocleidomastoid (SCM) is supplied by the spinal accessory nerve (CN XI) for motor function, and C2,C3 for proprioception. Trapezius is also supplied by CN XI (and C3,C4). Testing CN XI: ask patient to turn head against resistance (SCM) and shrug shoulders (trapezius). SCM injury causes torticollis.", difficulty:"easy"},
  { id:"ana_88", text:"A posterior mediastinal mass is MOST likely to be:", options:["Thymoma","Teratoma","Neurogenic tumor","Pericardial cyst"], correct:2, explanation:"Posterior mediastinal masses are predominantly neurogenic tumors (schwannomas, neurofibromas, ganglioneuromas, neuroblastomas) arising from the paravertebral sympathetic chain or intercostal nerves. Mnemonic for mediastinal masses by compartment: Anterior (4 T's: Thymoma, Teratoma, Thyroid, Terrible lymphoma); Middle (lymphoma, cysts); Posterior (neurogenic).", difficulty:"medium"},
  { id:"ana_89", text:"The atlanto-axial joint allows primarily which movement?", options:["Flexion and extension","Lateral flexion","Rotation of the head","All movements equally"], correct:2, explanation:"The median atlanto-axial joint (between dens of axis and anterior arch of atlas) allows rotation of the head (approximately 50% of total cervical rotation). The dens is held in place by the transverse ligament of atlas. Rupture of the transverse ligament (e.g., Down syndrome, rheumatoid arthritis) causes atlanto-axial instability and risk of spinal cord compression.", difficulty:"easy"},
  { id:"ana_90", text:"The celiac trunk branches into which three vessels?", options:["Left gastric, splenic, common hepatic arteries","Left gastric, right gastric, hepatic arteries","Gastroduodenal, superior mesenteric, inferior mesenteric arteries","Common hepatic, superior mesenteric, splenic arteries"], correct:0, explanation:"The celiac trunk (T12, from aorta) divides into: (1) left gastric artery (smallest, supplies lesser curvature and lower esophagus), (2) splenic artery (longest, tortuous, supplies spleen, pancreatic branches, left gastroepiploic), (3) common hepatic artery (divides into hepatic artery proper and gastroduodenal). Mnemonic: 'Left, Splenic, Common' or 'Let Surgeons Cut'.", difficulty:"easy"},
  { id:"ana_91", text:"The tricuspid valve is projected onto the chest wall at which location?", options:["Left 2nd intercostal space","Right 2nd intercostal space","Lower left sternal border (4th and 5th intercostal spaces)","Left 5th intercostal space, midclavicular line"], correct:2, explanation:"Heart valve auscultation areas: Aortic = right 2nd ICS; Pulmonary = left 2nd ICS; Tricuspid = lower left sternal border (4th-5th ICS); Mitral = left 5th ICS midclavicular line (apex). Murmurs radiate: aortic stenosis to carotids; mitral regurgitation to axilla; tricuspid regurgitation best heard at left lower sternal border.", difficulty:"medium"},
  { id:"ana_92", text:"Which type of joint is the hip joint?", options:["Plane synovial joint","Pivot synovial joint","Ball and socket synovial joint","Condylar synovial joint"], correct:2, explanation:"The hip (coxofemoral) joint is a ball and socket synovial joint - the femoral head (ball) articulates with the acetabulum (socket). It is the most stable joint in the body, due to depth of the acetabulum, labrum, ligaments (iliofemoral/Y-ligament of Bigelow being strongest), and surrounding muscles. Compare to shoulder (also ball-and-socket but less stable - more mobile).", difficulty:"easy"},
  { id:"ana_93", text:"The Stensen's duct (parotid duct) opens into the oral cavity opposite which tooth?", options:["Upper first molar","Upper second molar","Lower second molar","Upper second premolar"], correct:1, explanation:"The parotid duct (Stensen's duct) crosses the masseter muscle, pierces the buccinator, and opens into the oral vestibule opposite the upper second molar tooth. This is important in diagnosing parotitis - the duct opening may show pus. Wharton's duct (submandibular) opens at the sublingual papilla near the frenulum.", difficulty:"medium"},
  { id:"ana_94", text:"The posterior interventricular artery (posterior descending artery) most commonly arises from which vessel in right coronary dominance?", options:["Left anterior descending artery","Left circumflex artery","Right coronary artery","Ramus intermedius"], correct:2, explanation:"In right dominant circulation (~85% of people), the posterior descending artery (PDA) arises from the right coronary artery. In left dominant circulation (~15%), it arises from the left circumflex. Coronary dominance is determined by which artery supplies the PDA and the posterior part of the interventricular septum.", difficulty:"medium"},
  { id:"ana_95", text:"The clavicle is the FIRST bone to ossify in the fetal skeleton. It ossifies by which process?", options:["Endochondral ossification entirely","Intramembranous ossification entirely","Both intramembranous and endochondral ossification","Periosteal ossification"], correct:2, explanation:"The clavicle is unique - it ossifies by BOTH intramembranous ossification (medial 2/3, from two primary centers) and endochondral ossification (medial epiphysis - the last epiphysis to fuse in the body, at ~25 years). It is the first bone to ossify (5th week) and the last to finish ossifying (25 years). Also the most commonly fractured bone.", difficulty:"hard"},
  { id:"ana_96", text:"During a thyroidectomy, the parathyroid glands are at risk. Which vessel supplies the INFERIOR parathyroid glands?", options:["Superior thyroid artery","Inferior thyroid artery","Both superior and inferior thyroid arteries","Direct branches from the aorta"], correct:1, explanation:"Both superior and inferior parathyroid glands are predominantly supplied by the inferior thyroid artery (branch of thyrocervical trunk). This is why ligation of the inferior thyroid artery during thyroidectomy risks devascularizing the parathyroids and causing hypoparathyroidism (tetany, hypocalcemia). The parathyroids should be identified and preserved.", difficulty:"medium"},
  { id:"ana_97", text:"The basilic vein joins which vein to form the axillary vein?", options:["Cephalic vein","Brachial vein","Median cubital vein","Median antebrachial vein"], correct:1, explanation:"The basilic vein ascends along the medial forearm, pierces the deep fascia in the mid-arm, and joins with the brachial veins (venae comitantes of the brachial artery) to form the axillary vein at the lower border of the teres major. The cephalic vein drains into the axillary vein at the deltopectoral groove (cephalic vein pierces the clavipectoral fascia).", difficulty:"medium"},
  { id:"ana_98", text:"Peyer's patches are lymphoid aggregates found in which part of the gastrointestinal tract?", options:["Stomach","Duodenum","Ileum","Colon"], correct:2, explanation:"Peyer's patches are aggregations of lymphoid follicles (MALT - mucosa-associated lymphoid tissue) found predominantly in the lamina propria and submucosa of the ileum. They contain M cells (membranous/microfold cells) that sample luminal antigens. In Salmonella typhi infection, Peyer's patches undergo necrosis and ulceration, potentially causing intestinal perforation.", difficulty:"easy"},
  { id:"ana_99", text:"The ureter is crossed anteriorly by the gonadal vessels in the abdomen. At what level does the right ureter cross in front of the right gonadal vessel?", options:["At the pelvic brim","Just below the renal pelvis","At the level of L3-L4","In the retroperitoneum at approximately L2"], correct:2, explanation:"The right ureter is crossed anteriorly by the right gonadal vessels (testicular in males, ovarian in females) in the retroperitoneum at approximately L3-L4. This proximity is why right gonadal vein thrombosis can cause right ureteral obstruction (Ovarian vein syndrome in females). The right ureter then crosses the right iliac vessels at the pelvic brim.", difficulty:"hard"},
  { id:"ana_100", text:"The inguinal ligament is formed by the lower free edge of which abdominal wall muscle?", options:["Internal oblique","Transversus abdominis","External oblique aponeurosis","Rectus abdominis"], correct:2, explanation:"The inguinal ligament (Poupart's ligament) is formed by the folded-under lower edge of the external oblique aponeurosis, stretching from the anterior superior iliac spine (ASIS) to the pubic tubercle. The lacunar ligament is the medial expansion at the pubic tubercle. Below the inguinal ligament, the femoral vessels pass into the femoral triangle.", difficulty:"easy"},
  { id:"ana_101", text:"The hepatic acinus (Rappaport) is divided into zones based on blood flow. Hepatocytes most vulnerable to ischemia are in:", options:["Zone 1 (periportal)","Zone 2 (midzonal)","Zone 3 (centrilobular/perivenous)","Zone 4"], correct:2, explanation:"In the hepatic acinus: Zone 1 (periportal) receives the most oxygenated blood (first). Zone 3 (centrilobular, around central vein) receives the least oxygen and is most susceptible to ischemia and centrilobular necrosis (seen in right heart failure, Budd-Chiari). Zone 1 is most susceptible to toxins (phosphorus) and viral hepatitis preferentially damages zone 1.", difficulty:"medium"},
  { id:"ana_102", text:"The median umbilical ligament is the remnant of which fetal structure?", options:["Umbilical vein","Umbilical arteries","Urachus (allantois)","Vitello-intestinal duct"], correct:2, explanation:"The median umbilical ligament is the remnant of the urachus (allantois), running from the apex of the bladder to the umbilicus. The medial umbilical ligaments (two) are remnants of the umbilical arteries. The ligamentum teres hepatis is the remnant of the umbilical vein (left). Patent urachus causes urine leakage from the umbilicus.", difficulty:"medium"},
  { id:"ana_103", text:"The conjoint tendon (inguinal falx) is formed by the aponeuroses of which muscles?", options:["External and internal oblique","Internal oblique and transversus abdominis","Transversus abdominis and rectus abdominis","External oblique and transversus abdominis"], correct:1, explanation:"The conjoint tendon (inguinal falx) is formed by the fused lower fibers of the aponeuroses of internal oblique and transversus abdominis. It inserts into the pectineal line (pecten pubis) and pubic crest. It forms the medial part of the posterior wall of the inguinal canal and is sometimes used to repair the posterior wall in inguinal hernia repair (Bassini/Shouldice technique).", difficulty:"medium"},
  { id:"ana_104", text:"Which of the following is a feature of the RIGHT lung that distinguishes it from the LEFT lung?", options:["Has two lobes","Has an oblique fissure only","Has a horizontal fissure and three lobes","Has the cardiac notch"], correct:2, explanation:"Right lung: 3 lobes (upper, middle, lower), horizontal (minor) fissure + oblique (major) fissure, broader and shorter, more vertical main bronchus (aspirated foreign bodies more likely here). Left lung: 2 lobes (upper and lower), oblique fissure only, has cardiac notch and lingula (homologue of right middle lobe), longer and narrower.", difficulty:"easy"},
  { id:"ana_105", text:"The facial artery crosses the mandible at which point and is palpable?", options:["At the angle of mandible","At the anterior border of masseter","At the mental foramen","At the coronoid notch"], correct:1, explanation:"The facial artery crosses the inferior border of the mandible at the anterior border of the masseter muscle, where it can be palpated (facial pulse). It then winds upward to the nasolabial fold and ends as the angular artery at the medial canthus. This point is used for facial artery compression to reduce bleeding from the lower face.", difficulty:"medium"},
  { id:"ana_106", text:"The dentate (pectinate) line in the anal canal marks the boundary between which embryological structures?", options:["Endoderm and ectoderm at the proctodeum","Hindgut endoderm and proctodeal ectoderm","Midgut and hindgut junction","Cloaca and proctodeum"], correct:1, explanation:"The dentate (pectinate) line marks the junction of the hindgut endoderm (upper anal canal) and proctodeal ectoderm (lower anal canal). Above the line: mucosa (columnar), internal hemorrhoids, lymph to internal iliac nodes, sensation via autonomic nerves (painless). Below: stratified squamous epithelium, external hemorrhoids, lymph to inguinal nodes, sensation via pudendal nerve (painful).", difficulty:"medium"},
  { id:"ana_107", text:"The posterior inferior cerebellar artery (PICA) is a branch of which vessel?", options:["Basilar artery","Vertebral artery","Internal carotid artery","Anterior inferior cerebellar artery"], correct:1, explanation:"PICA is a branch of the vertebral artery (just before it joins to form the basilar artery). PICA supplies the lateral medulla and inferior cerebellum. Occlusion causes lateral medullary (Wallenberg) syndrome: ipsilateral facial pain/temperature loss, Horner's syndrome, palate/vocal cord paralysis, cerebellar ataxia; contralateral body pain/temperature loss.", difficulty:"medium"},
  { id:"ana_108", text:"The axillary nerve passes through which space to reach the deltoid muscle?", options:["Quadrangular space","Triangular space","Triangular interval","Quadrilateral space only"], correct:0, explanation:"The axillary nerve passes through the quadrangular (quadrilateral) space along with the posterior circumflex humeral artery. Boundaries of quadrangular space: teres minor (superior), teres major (inferior), long head of triceps (medial), surgical neck of humerus (lateral). Triangular space contains the circumflex scapular artery. Triangular interval (lower triangular space) contains the radial nerve.", difficulty:"medium"},
  { id:"ana_109", text:"Type II pneumocytes (granular pneumocytes) are responsible for:", options:["Gas exchange","Production of surfactant","Phagocytosis of debris","Barrier function of alveoli"], correct:1, explanation:"Type II pneumocytes produce pulmonary surfactant (dipalmitoyl phosphatidylcholine - DPPC), which reduces alveolar surface tension, preventing collapse. They also serve as stem cells to replace type I pneumocytes after injury. Type I pneumocytes (95% of alveolar surface) are flat cells responsible for gas exchange. Macrophages (dust cells) in the alveoli perform phagocytosis.", difficulty:"easy"},
  { id:"ana_110", text:"The middle meningeal artery is a branch of which artery and enters the skull through which foramen?", options:["External carotid artery; foramen spinosum","Internal carotid artery; foramen spinosum","External carotid artery; foramen ovale","Internal carotid artery; foramen ovale"], correct:0, explanation:"The middle meningeal artery is a branch of the maxillary artery (from external carotid artery). It enters the skull through the foramen spinosum in the greater wing of sphenoid. It runs in grooves on the inner surface of the temporal bone. Its anterior branch is vulnerable at the pterion. Rupture causes epidural hematoma (lens-shaped/biconvex on CT).", difficulty:"easy"},
  { id:"ana_111", text:"Which structure is immediately posterior to the manubriosternal joint (angle of Louis)?", options:["Second rib articulation","Bifurcation of the trachea (carina)","Aortic arch","All of the above"], correct:3, explanation:"The sternal angle (angle of Louis, manubriosternal joint) is a key anatomical landmark at T4-T5 level: (1) bifurcation of trachea (carina) posteriorly, (2) articulation of second costal cartilage (rib counting starts here), (3) arch of aorta begins and ends here, (4) superior mediastinum/inferior mediastinum boundary, (5) ligamentum arteriosum level, (6) azygos vein drains into SVC.", difficulty:"medium"},
  { id:"ana_112", text:"In a clinical exam, you find loss of sensation over the lateral palm and dorsum of thumb, but the thenar muscles are intact. Which nerve is involved?", options:["Median nerve at the wrist","Radial nerve (superficial branch)","Ulnar nerve","Median nerve at the elbow"], correct:1, explanation:"The superficial branch of the radial nerve supplies: lateral (radial) 3.5 fingers on the dorsum, thenar eminence dorsum. It is purely sensory - no motor supply. The radial nerve itself supplies the extensor compartment muscles, but the superficial branch supplies dorsal hand sensation. Compression can occur at the lateral wrist (cheiralgia paresthetica/Wartenberg syndrome).", difficulty:"hard"},
  { id:"ana_113", text:"The foramen ovale in the fetal heart allows blood to pass from:", options:["Right atrium to left atrium","Left atrium to right atrium","Right ventricle to left ventricle","Left ventricle to right ventricle"], correct:0, explanation:"The foramen ovale allows oxygenated blood from the placenta (via ductus venosus → IVC → right atrium) to pass from the right atrium to the left atrium, bypassing the lungs. At birth, increased left atrial pressure (due to lung expansion and pulmonary blood flow) closes the foramen ovale functionally. Complete closure occurs by 3 months in most individuals. Patent foramen ovale (PFO) persists in ~25%.", difficulty:"easy"},
  { id:"ana_114", text:"The sartorius muscle is supplied by which nerve and performs which movements?", options:["Femoral nerve; hip flexion, abduction, lateral rotation and knee flexion","Obturator nerve; hip adduction and knee flexion","Superior gluteal nerve; hip abduction","Femoral nerve; knee extension and hip flexion"], correct:0, explanation:"Sartorius (supplied by the femoral nerve, L2,L3) is the longest muscle in the body. It flexes, abducts, and laterally rotates the hip, and flexes the knee - allowing the cross-legged 'tailor's position.' It inserts into the pes anserinus on the medial tibia. Its name comes from Latin 'sartor' meaning tailor.", difficulty:"medium"},
  { id:"ana_115", text:"The posterior belly of the digastric muscle is supplied by which nerve?", options:["Mylohyoid nerve (V3)","Facial nerve (VII)","Glossopharyngeal nerve (IX)","Hypoglossal nerve (XII)"], correct:1, explanation:"The digastric muscle has dual nerve supply: anterior belly = mylohyoid nerve (branch of inferior alveolar nerve, V3); posterior belly = facial nerve (CN VII). This reflects their different embryological origins: anterior belly from 1st arch mesoderm, posterior belly from 2nd arch. The stylohyoid muscle is also supplied by CN VII (same branchial arch).", difficulty:"medium"},
  { id:"ana_116", text:"Which of the following describes the position of the kidneys in relation to the peritoneum?", options:["Intraperitoneal","Retroperitoneal (primary)","Retroperitoneal (secondary)","Subperitoneal"], correct:1, explanation:"The kidneys are PRIMARY retroperitoneal organs - they develop in the retroperitoneum and remain there. Other primary retroperitoneal structures: aorta, IVC, adrenal glands, ureter, esophagus (thoracic), rectum. Secondary retroperitoneal (originally intraperitoneal, became retroperitoneal): duodenum (2nd-4th parts), pancreas (body and tail), ascending and descending colon.", difficulty:"medium"},
  { id:"ana_117", text:"The thoracic duct receives lymph from all of the following EXCEPT:", options:["Lower limbs","Right side of the thorax","Abdomen and pelvis","Left upper limb"], correct:1, explanation:"The thoracic duct drains 3/4 of the body's lymph: lower limbs, pelvis, abdomen (including gut), left thorax, left upper limb, and left side of head and neck. The right lymphatic duct drains the RIGHT upper quadrant of the body: right upper limb, right thorax, and right side of head and neck. A chylothorax is more common on the left side.", difficulty:"medium"},
  { id:"ana_118", text:"The perineal body (central tendon of perineum) is located at which position?", options:["Anterior to the anus","Between the anus and coccyx","Between the vagina/bulb of penis and the anus","In the midline at the ischial tuberosity"], correct:2, explanation:"The perineal body (central tendon of perineum) is a fibromuscular node located between the vagina (females) or bulb of penis (males) and the anus, in the superficial perineal space. Multiple perineal muscles converge here: external anal sphincter, bulbospongiosus, transverse perinei. In females, it is important obstetric structure damaged in 3rd/4th degree perineal tears.", difficulty:"medium"},
  { id:"ana_119", text:"The Müllerian (paramesonephric) ducts in females fuse to form which structures?", options:["Ovaries and fallopian tubes","Uterus, cervix, upper vagina and fallopian tubes","Only the fallopian tubes","Vagina only"], correct:1, explanation:"The Müllerian (paramesonephric) ducts: upper parts = fallopian tubes; lower parts fuse in the midline to form the uterus, cervix, and upper 2/3 of vagina. The lower 1/3 of vagina forms from the urogenital sinus. Anti-Müllerian hormone (AMH) from Sertoli cells causes regression of Müllerian ducts in males. Failure of fusion → uterus didelphys (double uterus).", difficulty:"medium"},
  { id:"ana_120", text:"Brodmann area 4 corresponds to which functional cortical area?", options:["Primary somatosensory cortex","Primary motor cortex","Premotor cortex","Prefrontal cortex"], correct:1, explanation:"Brodmann area 4 = primary motor cortex (precentral gyrus, frontal lobe). Brodmann area 3,1,2 = primary somatosensory cortex (postcentral gyrus). Brodmann area 6 = premotor and supplementary motor cortex. Brodmann area 44,45 = Broca's speech area (left hemisphere). Brodmann area 17 = primary visual cortex (calcarine sulcus, occipital lobe).", difficulty:"medium"},
  { id:"ana_121", text:"The radial nerve descends in the spiral groove of the humerus with which artery?", options:["Anterior circumflex humeral artery","Deep brachial (profunda brachii) artery","Posterior circumflex humeral artery","Superior ulnar collateral artery"], correct:1, explanation:"The radial nerve enters the posterior compartment of the arm by piercing the lateral intermuscular septum, and travels with the deep brachial (profunda brachii) artery in the spiral groove of the humerus. Midshaft humeral fractures can injure both. The radial nerve then pierces the lateral intermuscular septum to enter the anterior compartment in the lateral cubital region.", difficulty:"medium"},
  { id:"ana_122", text:"Which cells form the myelin sheath in the CENTRAL nervous system?", options:["Schwann cells","Astrocytes","Microglia","Oligodendrocytes"], correct:3, explanation:"Myelination: CNS = oligodendrocytes (one oligodendrocyte myelinates multiple axons); PNS = Schwann cells (one Schwann cell myelinates one axon segment). Astrocytes provide structural and metabolic support. Microglia are CNS macrophages. Multiple sclerosis involves demyelination of CNS (oligodendrocyte damage). Guillain-Barré involves PNS demyelination.", difficulty:"easy"},
  { id:"ana_123", text:"The scala vestibuli and scala tympani of the cochlea are filled with which fluid?", options:["Endolymph (high K+)","Perilymph (high Na+)","Endolymph in vestibuli, perilymph in tympani","Perilymph in both, connected at the helicotrema"], correct:3, explanation:"Scala vestibuli and scala tympani are filled with perilymph (similar to extracellular fluid, high Na+, low K+). They communicate at the apex of the cochlea at the helicotrema. The scala media (cochlear duct) between them contains endolymph (high K+, low Na+ - unique ionic composition produced by stria vascularis). The organ of Corti sits on the basilar membrane.", difficulty:"hard"},
  { id:"ana_124", text:"The pudendal nerve (S2,S3,S4) exits and re-enters the pelvis via which structures?", options:["Greater sciatic foramen only","Lesser sciatic foramen only","Greater sciatic foramen, then crosses the ischial spine, then enters through the lesser sciatic foramen","Through the obturator foramen"], correct:2, explanation:"The pudendal nerve exits the pelvis via the greater sciatic foramen (below piriformis), crosses the ischial spine (with pudendal vessels), and re-enters the perineum via the lesser sciatic foramen to travel in the pudendal canal (Alcock's canal) in the lateral wall of the ischiorectal fossa. Pudendal nerve block is performed at the ischial spine.", difficulty:"hard"},
  { id:"ana_125", text:"The transpyloric plane (of Addison) at L1 level passes through all EXCEPT:", options:["Pylorus of stomach","Fundus of gallbladder","Origin of superior mesenteric artery","Hilum of kidneys"], correct:1, explanation:"The transpyloric plane (Addison's plane) at L1/L2 level passes through: pylorus, fundus of gallbladder, tips of 9th costal cartilages, hilum of both kidneys, origin of SMA, neck of pancreas, D1/D2 junction, termination of spinal cord (L1-L2). The gallbladder FUNDUS is at this level but its body extends superiorly. The liver hilum is at the porta hepatis.", difficulty:"hard"},
  { id:"ana_126", text:"In the thorax, the azygos vein drains into which vessel?", options:["Left brachiocephalic vein","Superior vena cava","Right subclavian vein","Inferior vena cava"], correct:1, explanation:"The azygos vein arches over the right lung root and drains into the superior vena cava (at T4-T5 level). It drains the posterior thoracic wall (intercostal veins), right bronchial veins, and hemiazygos veins. The azygos system is a crucial collateral pathway when the SVC or IVC is obstructed (Budd-Chiari, SVC syndrome).", difficulty:"medium"},
  { id:"ana_127", text:"Broca's area is located in which part of the brain and controls which function?", options:["Left posterior temporal lobe; speech comprehension","Left inferior frontal gyrus (areas 44,45); speech production","Right inferior frontal gyrus; written language","Left angular gyrus; reading and writing"], correct:1, explanation:"Broca's area (Brodmann areas 44,45) is in the left inferior frontal gyrus (posterior part). It controls speech production/motor programming of speech. Lesion causes expressive (Broca's) aphasia: non-fluent speech with good comprehension. Wernicke's area (area 22, left superior temporal gyrus) controls speech comprehension. Lesion causes receptive (Wernicke's) aphasia: fluent but meaningless speech.", difficulty:"easy"},
  { id:"ana_128", text:"The stylomastoid foramen transmits which structure?", options:["CN IX","CN VII","Styloid process","Auriculotemporal nerve"], correct:1, explanation:"The stylomastoid foramen transmits the facial nerve (CN VII) as it exits the skull between the styloid and mastoid processes. The nerve then enters the parotid gland. Fractures of the temporal bone at the stylomastoid foramen cause LMN facial nerve palsy. The facial canal within the temporal bone transmits CN VII before it exits at this foramen.", difficulty:"easy"},
  { id:"ana_129", text:"The dermatome of the great toe (hallux) corresponds to which spinal nerve root?", options:["L3","L4","L5","S1"], correct:2, explanation:"L5 dermatome: dorsum of foot, first web space, great toe, medial 3 toes, anterior lateral leg. L4: medial foot and medial malleolus. S1: sole, lateral foot, small toe, posterior calf. L5 root compression (L4/L5 disc) causes weakness of dorsiflexion, great toe extension (extensor hallucis longus), and loss of sensation in the first web space.", difficulty:"medium"},
  { id:"ana_130", text:"The coracobrachialis muscle is pierced by which nerve?", options:["Axillary nerve","Radial nerve","Median nerve","Musculocutaneous nerve"], correct:3, explanation:"The musculocutaneous nerve (C5,C6,C7) from the lateral cord of the brachial plexus pierces the coracobrachialis muscle and then runs between biceps brachii and brachialis, supplying all three muscles. It continues as the lateral cutaneous nerve of the forearm. Injury (rare) causes weakness of elbow flexion and loss of forearm lateral sensation.", difficulty:"medium"},
  { id:"ana_131", text:"The Kupffer cells in the liver are derived from which cell lineage?", options:["Endodermal hepatic stem cells","Monocyte/macrophage lineage (mesoderm)","Stellate cell precursors","Biliary epithelium"], correct:1, explanation:"Kupffer cells are liver-resident macrophages derived from bone marrow monocyte/macrophage lineage (mononuclear phagocyte system). They are found within the sinusoidal lumen, attached to endothelial cells. They phagocytose bacteria, old red blood cells, and debris from portal blood. Activation of Kupffer cells contributes to liver injury in alcoholic hepatitis and NAFLD.", difficulty:"medium"},
  { id:"ana_132", text:"In which direction does the right ureter deviate when the bladder is full versus empty?", options:["It deviates medially when the bladder is full","It deviates laterally when the bladder is full","Position does not change","It descends lower as bladder fills"], correct:0, explanation:"As the urinary bladder fills and expands superiorly and posteriorly, it can displace the ureters slightly medially. The ureters enter the posterior wall of the bladder obliquely at the ureteric orifices (ureterovesical junctions). The oblique passage through the bladder wall creates a one-way valve mechanism preventing vesicoureteric reflux when intravesical pressure rises.", difficulty:"hard"},
  { id:"ana_133", text:"The blood supply to the spinal cord depends on the anterior spinal artery supplying what percentage of the cord?", options:["25%","50%","75%","90%"], correct:2, explanation:"The anterior spinal artery (formed by contributions from both vertebral arteries) supplies the anterior 2/3 (75%) of the spinal cord, including the corticospinal tracts and anterior horn. The posterior spinal arteries (two) supply the posterior 1/3 (dorsal columns). Anterior spinal artery syndrome: bilateral loss of motor function and pain/temperature (sparing posterior columns = preserved proprioception/vibration).", difficulty:"medium"},
  { id:"ana_134", text:"The gubernaculum in males guides testicular descent to the scrotum and persists as which adult structure?", options:["Suspensory ligament of testis","Scrotal ligament","Round ligament of uterus (female equivalent)","Processus vaginalis"], correct:1, explanation:"The gubernaculum guides testicular descent from the abdomen to the scrotum during weeks 7-36 of development. In adult males, its remnant is the scrotal ligament (connects the lower pole of the testis/epididymis to the scrotum). In females, the homologous structure persists as the ovarian ligament (from ovary to uterus) and round ligament of the uterus (uterus to labium majus).", difficulty:"hard"},
  { id:"ana_135", text:"The carinal angle (subcarinal angle) is normally less than:", options:["60 degrees","70 degrees","80 degrees","90 degrees"], correct:1, explanation:"The trachea bifurcates at the carina (T4-T5 level, angle of Louis), and the normal subcarinal angle is <70°. Enlargement of subcarinal lymph nodes (e.g., sarcoidosis, lung cancer, lymphoma) widens this angle. On barium swallow, an enlarged left atrium also widens the carina angle and elevates the left main bronchus, causing 'double shadow' and 'splayed carina.'", difficulty:"hard"},
  { id:"ana_136", text:"The iliotibial band (IT band) is the thickening of which structure?", options:["Tensor fascia lata muscle fascia","Deep fascia of the thigh (fascia lata)","Lateral intermuscular septum","Biceps femoris tendon"], correct:1, explanation:"The iliotibial (IT) band is a longitudinal thickening of the fascia lata (deep fascia of the thigh) on the lateral side. It is reinforced by the tensor fascia lata and gluteus maximus. It inserts into Gerdy's tubercle on the lateral tibial condyle. IT band syndrome is a common overuse injury in runners causing lateral knee pain.", difficulty:"easy"},
  { id:"ana_137", text:"The liver is divided into functional segments based on the distribution of which vessels?", options:["Hepatic veins only","Portal vein and hepatic artery branches","Portal vein branches only","Bile ducts only"], correct:1, explanation:"The Couinaud segmental anatomy divides the liver into 8 functional segments (I-VIII) based on the distribution of portal vein and hepatic artery branches (and bile ducts). Each segment has its own portal triad and hepatic vein drainage, allowing independent surgical resection. The hepatic veins divide the liver into left, middle, and right sectors (between segments).", difficulty:"medium"},
  { id:"ana_138", text:"The musculocutaneous nerve is a branch of which cord of the brachial plexus?", options:["Posterior cord","Medial cord","Lateral cord","All three cords"], correct:2, explanation:"The lateral cord (C5,C6,C7) gives rise to: musculocutaneous nerve, lateral pectoral nerve, and the lateral root of the median nerve. The medial cord gives: ulnar nerve, medial pectoral nerve, medial cutaneous nerves, and medial root of median nerve. The posterior cord gives: radial nerve, axillary nerve, thoracodorsal nerve, subscapular nerves.", difficulty:"medium"},
  { id:"ana_139", text:"The levator ani muscle is supplied by which nerves?", options:["Pudendal nerve only","Nerve to levator ani (S3,S4) and perineal branch of pudendal nerve","Inferior rectal nerve only","Pelvic splanchnic nerves (S2,S3,S4)"], correct:1, explanation:"Levator ani has dual innervation: (1) nerve to levator ani (direct perineal branches from S3,S4) on its superior (pelvic) surface, and (2) inferior rectal nerve and perineal branch of pudendal nerve (S2,S3,S4) on its inferior (perineal) surface. This dual supply is important in pelvic floor dysfunction, where both obstetric and nerve injuries may be involved.", difficulty:"hard"},
  { id:"ana_140", text:"The left gastric artery anastomoses with which artery along the lesser curvature of the stomach?", options:["Right gastroepiploic artery","Right gastric artery","Left gastroepiploic artery","Short gastric arteries"], correct:1, explanation:"Along the lesser curvature: left gastric artery (from celiac trunk) anastomoses with right gastric artery (from hepatic artery proper). Along the greater curvature: right gastroepiploic artery (from gastroduodenal artery) anastomoses with left gastroepiploic artery (from splenic artery). Short gastric arteries (from splenic artery) supply the fundus.", difficulty:"medium"},
  { id:"ana_141", text:"Which bone contains the groove for the ulnar nerve at the elbow?", options:["Lateral epicondyle of humerus","Medial epicondyle of humerus","Olecranon","Head of radius"], correct:1, explanation:"The ulnar nerve passes behind the medial epicondyle of the humerus in the cubital tunnel (ulnar groove). Pressure here (e.g., leaning on elbows) or fractures of the medial epicondyle cause 'funny bone' sensation or ulnar nerve palsy. Tardy ulnar palsy occurs years after childhood lateral condyle fractures due to cubitus valgus deformity.", difficulty:"easy"},
  { id:"ana_142", text:"The middle ear is connected to the nasopharynx via which structure?", options:["Internal auditory meatus","External acoustic meatus","Pharyngotympanic (Eustachian) tube","Mastoid antrum"], correct:2, explanation:"The Eustachian (pharyngotympanic/auditory) tube connects the middle ear (tympanic cavity) to the nasopharynx, equalizing middle ear pressure with atmospheric pressure. It is normally closed but opens during swallowing, yawning, and chewing. Dysfunction causes otitis media with effusion ('glue ear'). In infants, it is shorter, wider, and more horizontal, making middle ear infections more common.", difficulty:"easy"},
  { id:"ana_143", text:"The gracilis muscle is the most medial muscle of the thigh. Its nerve supply and primary action are:", options:["Femoral nerve; knee extension","Obturator nerve; hip adduction and knee flexion","Superior gluteal nerve; hip abduction","Sciatic nerve; knee flexion"], correct:1, explanation:"Gracilis (obturator nerve, L2,L3): most medial thigh muscle; adducts hip and flexes knee. It inserts into the pes anserinus on the medial tibia. Gracilis is used as a free muscle flap in reconstructive surgery (e.g., pharyngeal or perianal reconstruction) because of its long vascular pedicle and expendability.", difficulty:"medium"},
  { id:"ana_144", text:"The supratrochlear and supraorbital arteries are branches of which vessel and supply which area?", options:["External carotid artery; temporal region","Ophthalmic artery (internal carotid); forehead and scalp","Maxillary artery; orbit","Facial artery; nose"], correct:1, explanation:"The supratrochlear and supraorbital arteries are branches of the ophthalmic artery (from the internal carotid artery). They supply the forehead and anterior scalp. The scalp receives anastomotic supply from both ICA (via ophthalmic) and ECA (via superficial temporal, posterior auricular, occipital). This rich anastomosis means scalp wounds bleed profusely.", difficulty:"medium"},
  { id:"ana_145", text:"The pontine nuclei relay information from which cortical area to the cerebellum?", options:["Cerebral cortex (all areas) → pontine nuclei → contralateral cerebellum via middle cerebellar peduncle","Cerebellum → pontine nuclei → cortex","Spinal cord → pontine nuclei → cerebellum","Thalamus → pontine nuclei → cerebellum"], correct:0, explanation:"The corticopontocerebellar pathway: cerebral cortex → corticospine fibers → pontine nuclei (ipsilateral) → cross midline → middle cerebellar peduncle → contralateral cerebellar cortex. This allows the cerebral cortex to modulate cerebellar coordination of voluntary movement. The middle cerebellar peduncle (brachium pontis) is the largest peduncle.", difficulty:"medium"},
  { id:"ana_146", text:"The thoracoepigastric vein is a clinical route of venous drainage when which vein is obstructed?", options:["Axillary vein","Inferior vena cava","Superior vena cava","Portal vein"], correct:1, explanation:"The thoracoepigastric vein connects the lateral thoracic vein (draining into axillary → SVC) to the superficial epigastric vein (draining into femoral → external iliac → IVC). In IVC obstruction, collateral flow occurs through this route (upward flow in trunk veins). In SVC obstruction, flow is downward. Caput medusae (portal-systemic anastomoses around umbilicus) occurs in portal hypertension.", difficulty:"hard"},
  { id:"ana_147", text:"The rotator interval of the shoulder is the triangular space between which two muscles?", options:["Supraspinatus and infraspinatus","Subscapularis and supraspinatus","Teres minor and infraspinatus","Subscapularis and teres major"], correct:1, explanation:"The rotator interval is a triangular anatomical space in the shoulder between the anterior edge of supraspinatus superiorly and the superior edge of subscapularis inferiorly. It contains the coracohumeral ligament, superior glenohumeral ligament, and long head of biceps tendon. Disruption contributes to shoulder instability. Contracture can cause adhesive capsulitis.", difficulty:"hard"},
  { id:"ana_148", text:"The Wharton's jelly of the umbilical cord is composed of:", options:["Dense fibrous connective tissue","Loose mucous (gelatinous) connective tissue rich in hyaluronic acid","Adipose tissue","Cartilaginous tissue"], correct:1, explanation:"Wharton's jelly is the loose mucous/gelatinous connective tissue of the umbilical cord, rich in hyaluronic acid, proteoglycans, and water. It surrounds the umbilical vessels (two arteries, one vein) and provides cushioning and protection. It contains mesenchymal stem cells of interest for regenerative medicine. A single umbilical artery is associated with renal anomalies.", difficulty:"medium"},
  { id:"ana_149", text:"The Horner's syndrome associated with a Pancoast (superior sulcus) tumor is due to involvement of which structure?", options:["Brachial plexus (C8,T1)","Sympathetic chain in the apex of the lung/T1 level","Vagus nerve","Phrenic nerve"], correct:1, explanation:"A Pancoast tumor (superior sulcus tumor, usually squamous cell carcinoma) at the apex of the lung can invade the sympathetic chain (stellate ganglion, T1) causing ipsilateral Horner's syndrome (ptosis, miosis, anhidrosis, enophthalmos). It can also invade the C8,T1 nerve roots causing medial arm/hand pain and weakness (Klumpke-like picture). Destruction of ribs (1st and 2nd) may also occur.", difficulty:"medium"},
  { id:"ana_150", text:"The ampulla of Vater (hepatopancreatic ampulla) is located in which part of the duodenum?", options:["First part (D1)","Second part (D2) at the posteromedial wall","Third part (D3)","Fourth part (D4)"], correct:1, explanation:"The ampulla of Vater (hepatopancreatic ampulla) opens into the posteromedial wall of the second part (D2) of the duodenum at the major duodenal papilla. The minor papilla (accessory pancreatic duct) is 2cm proximal. Cancer at the head of pancreas obstructs this ampulla causing painless obstructive jaundice (Courvoisier's sign: palpable non-tender gallbladder).", difficulty:"easy"},
  { id:"ana_151", text:"The geniculate ganglion of CN VII carries cell bodies for which type of neurons?", options:["Motor neurons for facial muscles","General somatic afferent neurons","Special visceral afferent (taste) from anterior 2/3 of tongue","Preganglionic parasympathetic neurons"], correct:2, explanation:"The geniculate ganglion (geniculum = 'little knee', as CN VII bends sharply here in the facial canal) contains cell bodies of special visceral afferent (SVA) neurons carrying taste from the anterior 2/3 of the tongue (via chorda tympani) and general somatic afferent neurons from the auricle. The greater superficial petrosal nerve also branches here (carrying preganglionic parasympathetics to pterygopalatine ganglion for lacrimal/nasal glands).", difficulty:"hard"},
  { id:"ana_152", text:"Which of the following muscles does NOT form the rotator cuff?", options:["Supraspinatus","Infraspinatus","Teres minor","Teres major"], correct:3, explanation:"The rotator cuff (SITS muscles): Supraspinatus (abduction), Infraspinatus (external rotation), Teres MINOR (external rotation), Subscapularis (internal rotation). Teres MAJOR is NOT part of the rotator cuff. Teres major is supplied by lower subscapular nerve and performs extension, adduction, and medial rotation of the arm. It forms the posterior axillary fold with latissimus dorsi.", difficulty:"easy"},
  { id:"ana_153", text:"A patient with a midline abdominal incision has their rectus abdominis disrupted. The linea alba is avascular. Which vessels supply the rectus abdominis?", options:["Inferior epigastric artery and superior epigastric artery","External iliac artery directly","Superficial epigastric artery only","Musculophrenic artery and inferior epigastric"], correct:0, explanation:"The rectus abdominis receives blood from: superior epigastric artery (terminal branch of internal thoracic/internal mammary artery) entering superiorly, and inferior epigastric artery (branch of external iliac) entering inferiorly. These anastomose within the muscle. The TRAM flap (transverse rectus abdominis myocutaneous flap) used in breast reconstruction relies on this blood supply.", difficulty:"medium"},
  { id:"ana_154", text:"Which of the following joints is a primary cartilaginous joint (synchondrosis)?", options:["Pubic symphysis","Intervertebral disc","Costochondral joint","Temporomandibular joint"], correct:2, explanation:"Synchondroses (primary cartilaginous joints, united by hyaline cartilage): costochondral joints, epiphyseal (growth) plates, sternochondral joint (1st rib). Symphyses (secondary cartilaginous, united by fibrocartilage): pubic symphysis, intervertebral discs, manubriosternal joint. The TMJ is a synovial joint (condylar type) with an articular disc.", difficulty:"medium"},
  { id:"ana_155", text:"During mastoidectomy, which structure must be identified to avoid facial nerve injury?", options:["Lateral semicircular canal and the short process of incus","Tympanic membrane","Malleus head","External auditory canal"], correct:0, explanation:"During mastoidectomy, the lateral (horizontal) semicircular canal and the short process (lateral process) of the incus are key landmarks for locating the facial nerve. The facial nerve runs just below the lateral semicircular canal and medial to the posterior canal wall. Identifying these prevents inadvertent facial nerve damage (causing LMN facial palsy).", difficulty:"hard"},
  { id:"ana_156", text:"The ductus venosus in fetal circulation connects which vessels?", options:["Umbilical vein to inferior vena cava (bypassing liver)","Umbilical artery to portal vein","Portal vein to hepatic vein","Ductus arteriosus to the left atrium"], correct:0, explanation:"The ductus venosus connects the left branch of the portal vein (carrying oxygenated blood from the umbilical vein) directly to the IVC, bypassing most of the liver. This allows about 50% of umbilical venous blood to bypass hepatic circulation. At birth, it closes to become the ligamentum venosum. Failure of closure is rare (patent ductus venosus).", difficulty:"medium"},
  { id:"ana_157", text:"The lymph nodes of Virchow (Troisier's sign) are located where and indicate what?", options:["Right cervical nodes; right lung cancer","Left supraclavicular nodes; abdominal malignancy (especially stomach cancer)","Inguinal nodes; pelvic malignancy","Left axillary nodes; breast cancer"], correct:1, explanation:"Virchow's node (sentinel node, signal node) is the left supraclavicular lymph node. Enlargement (Troisier's sign) indicates metastasis from abdominal malignancy (particularly gastric cancer), as the thoracic duct drains into the left subclavian vein near these nodes. However, any abdominal, pelvic, or thoracic malignancy can cause left supraclavicular adenopathy.", difficulty:"medium"},
  { id:"ana_158", text:"The posterior wall of the axilla is formed by which muscles?", options:["Pectoralis major and minor","Serratus anterior and subscapularis","Subscapularis, teres major, and latissimus dorsi","Latissimus dorsi and pectoralis minor"], correct:2, explanation:"Axilla walls: anterior = pectoralis major (superficial), pectoralis minor and clavipectoral fascia (deep); posterior = subscapularis (upper), teres major and latissimus dorsi (lower); medial = serratus anterior and upper ribs; lateral = bicipital groove of humerus. The axillary artery, vein, and brachial plexus cords traverse the axilla.", difficulty:"medium"},
  { id:"ana_159", text:"The Bell's palsy (idiopathic facial nerve palsy) causes LMN facial nerve palsy. Which finding distinguishes LMN from UMN facial nerve palsy?", options:["Loss of taste","Involvement of the forehead muscles (frontalis) in LMN palsy","Hyperacusis","All of the above distinguish LMN from UMN"], correct:1, explanation:"In UMN facial palsy (stroke, cortical lesion): forehead is SPARED because frontalis has bilateral cortical representation. In LMN palsy (Bell's palsy, facial nerve damage at any point from nucleus to periphery): ALL ipsilateral facial muscles are affected including the FOREHEAD. Bell's palsy: idiopathic LMN palsy, associated with HSV-1 reactivation; treated with steroids ± acyclovir.", difficulty:"easy"},
  { id:"ana_160", text:"The coronary ligament of the liver attaches the liver to the diaphragm. The bare area of the liver (between the two layers of coronary ligament) is a site where:", options:["Portal hypertension develops","Lymph from the liver drains directly into the diaphragmatic lymphatics","The liver is most accessible surgically","No clinical significance"], correct:1, explanation:"The bare area of the liver is where the liver is directly apposed to the diaphragm without peritoneal covering (between the superior and inferior layers of the coronary ligament). Lymphatics from the liver drain through the bare area into the diaphragmatic lymphatics (and then to the mediastinal lymph nodes). In right-sided hepatic abscess, infection can spread through the bare area to the right pleural cavity.", difficulty:"hard"},
  { id:"ana_161", text:"The peroneus (fibularis) longus tendon crosses the sole of the foot and inserts into which bone?", options:["Calcaneus","Navicular","Medial cuneiform and base of 1st metatarsal","Base of 5th metatarsal"], correct:2, explanation:"Fibularis (peroneus) longus tendon enters the foot from the lateral side (inserts into base of 5th metatarsal via fibularis brevis), then turns medially crossing the sole to insert into the medial cuneiform and base of the 1st metatarsal. This supports the transverse arch of the foot. It is supplied by the superficial fibular nerve (L5,S1).", difficulty:"medium"},
  { id:"ana_162", text:"The articular surface of the patella articulates with which part of the femur?", options:["Medial femoral condyle","Lateral femoral condyle","Patellar surface (trochlear groove) of femur","Intercondylar notch"], correct:2, explanation:"The patella (largest sesamoid bone) articulates with the patellar surface (trochlear groove/facies patellaris) on the anterior distal femur. It glides in this groove during knee flexion/extension. The patella increases the mechanical advantage of the quadriceps by increasing the lever arm. Patellar dislocation usually occurs laterally (stronger pull of lateral structures).", difficulty:"easy"},
  { id:"ana_163", text:"The Sibson's fascia (suprapleural membrane) covers the apex of the lung. It is a thickening of which structure?", options:["Costal pleura","Endothoracic fascia","Scalene fascia","Prevertebral fascia"], correct:1, explanation:"Sibson's fascia (suprapleural membrane) is a dome-shaped thickening of the endothoracic fascia that covers the cervical pleura and apex of the lung. It attaches to the inner border of the first rib and the transverse process of C7. It protects the apex of the lung from the neck structures and is tense in the cadaver (helps maintain lung shape).", difficulty:"hard"},
  { id:"ana_164", text:"Which of the following is a TRUE statement about the femoral nerve?", options:["It exits the pelvis through the femoral canal","It supplies the knee extensors (quadriceps) via the femoral nerve (L2,3,4)","It lies medial to the femoral artery in the femoral sheath","It is responsible for the ankle jerk"], correct:1, explanation:"The femoral nerve (L2,L3,L4) exits the pelvis under the inguinal ligament LATERAL to the femoral artery (and outside the femoral sheath). It supplies: iliopsoas (hip flexion), quadriceps (knee extension - L3,L4), sartorius, pectineus, and skin of medial thigh/leg (saphenous nerve). The femoral sheath contains (lateral to medial): femoral artery, femoral vein, femoral canal (lymphatics). Nerve is outside the sheath.", difficulty:"medium"},
  { id:"ana_165", text:"In the anatomical position, the palm faces:", options:["Posteriorly","Medially","Anteriorly","Laterally"], correct:2, explanation:"In the anatomical position, the body stands erect, facing forward, with upper limbs at the sides and palms facing ANTERIORLY (forward). This is the standard reference position for anatomical descriptions. With elbows straight, the forearm is supinated (radius and ulna are parallel, not crossed) in the anatomical position.", difficulty:"easy"},
  { id:"ana_166", text:"The tendon of which muscle can be seen and palpated at the wrist and is used for palmaris longus identification?", options:["Flexor carpi ulnaris","Flexor carpi radialis","Palmaris longus","Flexor pollicis longus"], correct:2, explanation:"Palmaris longus tendon is visible and palpable in the midline at the wrist when the patient opposes the thumb and little finger against resistance. It inserts into the palmar aponeurosis. It is absent in 10-15% of people (unilaterally or bilaterally). It is the most commonly used tendon graft in surgery (e.g., anterior cruciate ligament repair) because its absence causes no functional deficit.", difficulty:"easy"},
  { id:"ana_167", text:"The fovea centralis of the retina is specialized for which type of vision?", options:["Peripheral vision and night vision","High acuity color (day) vision","Motion detection","Black and white vision at low light"], correct:1, explanation:"The fovea centralis (in the macula lutea) contains the highest density of cone photoreceptors and is specialized for high-acuity color (photopic) vision. No rods are present in the fovea. The fovea is the point of fixation and maximum visual acuity. The optic disc (blind spot) is located ~15° nasal to the fovea. The retinal periphery has more rods for low-light (scotopic) and peripheral vision.", difficulty:"easy"},
  { id:"ana_168", text:"The profunda femoris (deep femoral) artery provides blood supply via which branches to the femoral head?", options:["Superficial circumflex iliac artery","Medial and lateral circumflex femoral arteries","Perforating arteries directly","Obturator artery"], correct:1, explanation:"The profunda femoris gives medial and lateral circumflex femoral arteries. The medial circumflex femoral artery is the MOST important supply to the femoral head (via retinacular arteries along the femoral neck). Femoral neck fractures disrupt these retinacular vessels, risking avascular necrosis of the femoral head. The artery of the ligamentum teres (obturator branch) supplies only a small area near the fovea.", difficulty:"medium"},
  { id:"ana_169", text:"The lesser omentum extends between which structures?", options:["Stomach and transverse colon","Liver and stomach/duodenum","Spleen and stomach","Stomach and spleen"], correct:1, explanation:"The lesser omentum connects the liver (porta hepatis and fissure for ligamentum venosum) to the lesser curvature of the stomach and first 2cm of duodenum. It has two parts: hepatogastric ligament (to stomach) and hepatoduodenal ligament (to duodenum, containing portal triad). The greater omentum hangs from the greater curvature of the stomach.", difficulty:"easy"},
  { id:"ana_170", text:"The trochanteric anastomosis provides blood supply to the hip joint. Which of the following arteries does NOT contribute to this anastomosis?", options:["Medial circumflex femoral artery","Lateral circumflex femoral artery","Obturator artery","Inferior epigastric artery"], correct:3, explanation:"The cruciate anastomosis around the hip/trochanteric region is formed by: medial circumflex femoral, lateral circumflex femoral, inferior gluteal, and first perforating artery. The obturator artery supplies the acetabulum and the artery of the ligamentum teres. The inferior epigastric artery supplies the anterior abdominal wall and is NOT part of hip anastomosis.", difficulty:"hard"},
  { id:"ana_171", text:"Sensory innervation of the dura mater in the posterior cranial fossa is provided by:", options:["CN V (trigeminal nerve)","CN X (vagus nerve) and upper cervical nerves","CN IX alone","CN VII"], correct:1, explanation:"Dural innervation by region: anterior cranial fossa = ophthalmic nerve (V1); middle cranial fossa = maxillary (V2) and mandibular (V3); posterior cranial fossa = vagus nerve (CN X, via recurrent meningeal branch) and C1-C3 nerve roots (via the tentorial nerve from C1 and meningeal branches). This is why posterior fossa pathology can cause occipital headache.", difficulty:"hard"},
  { id:"ana_172", text:"The zona glomerulosa of the adrenal cortex produces which hormone?", options:["Cortisol","Aldosterone","DHEA and androgens","Epinephrine"], correct:1, explanation:"Adrenal cortex zones (GFR mnemonic = 'Go Find Rex'): Glomerulosa = aldosterone (mineralocorticoid, regulated by angiotensin II and K+); Fasciculata = cortisol (glucocorticoid, regulated by ACTH); Reticularis = androgens (DHEA, androstenedione). The medulla produces catecholamines (epinephrine > norepinephrine). Primary hyperaldosteronism (Conn's syndrome) = zona glomerulosa adenoma.", difficulty:"easy"},
  { id:"ana_173", text:"Which part of the nephron is impermeable to water even in the presence of ADH?", options:["Proximal convoluted tubule","Thin descending limb of loop of Henle","Thin ascending limb of loop of Henle","Collecting duct"], correct:2, explanation:"The thin and thick ascending limb of the loop of Henle are ALWAYS impermeable to water (no aquaporins), regardless of ADH. This is key to the countercurrent multiplier mechanism. NaCl is reabsorbed here (diluting the tubular fluid), creating the medullary osmotic gradient. ADH acts on the collecting duct to increase water permeability (aquaporin-2 insertion).", difficulty:"medium"},
  { id:"ana_174", text:"The processus vaginalis is a peritoneal diverticulum. Incomplete obliteration leads to which clinical condition?", options:["Direct inguinal hernia","Femoral hernia","Indirect inguinal hernia","Umbilical hernia"], correct:2, explanation:"The processus vaginalis is a peritoneal outgrowth that precedes testicular descent through the inguinal canal. It normally obliterates after birth. Incomplete obliteration allows abdominal contents to herniate through the deep inguinal ring → indirect inguinal hernia. A patent processus vaginalis filled with fluid (without hernia) = hydrocele of the spermatic cord.", difficulty:"easy"},
  { id:"ana_175", text:"The appendicular skeleton includes all EXCEPT:", options:["Upper limb bones","Lower limb bones","Pelvic girdle","Sternum"], correct:3, explanation:"The appendicular skeleton (126 bones) consists of: upper limbs (64 bones including pectoral girdle), lower limbs (62 bones including pelvic girdle). The axial skeleton (80 bones) includes: skull, vertebral column, ribs, and sternum. The sternum is thus part of the AXIAL skeleton, not the appendicular skeleton.", difficulty:"easy"},
  { id:"ana_176", text:"The superior mesenteric artery (SMA) arises from the aorta at which vertebral level?", options:["T12","L1","L2","L3"], correct:1, explanation:"The SMA arises from the anterior abdominal aorta at L1 (approximately 1cm below the celiac trunk at T12). The SMA supplies: small intestine (from DJ flexure to mid-transverse colon), cecum, ascending colon, and transverse colon. SMA occlusion causes ischemia of this region presenting with severe periumbilical pain out of proportion to examination findings.", difficulty:"medium"},
  { id:"ana_177", text:"The Rathke's pouch, an ectodermal outgrowth from the roof of the stomodeum, gives rise to which structure?", options:["Posterior pituitary (neurohypophysis)","Anterior pituitary (adenohypophysis)","Pineal gland","Hypothalamus"], correct:1, explanation:"Rathke's pouch (oral ectoderm from stomodeum roof) → adenohypophysis (anterior pituitary) = pars distalis, pars tuberalis, pars intermedia. The neurohypophysis (posterior pituitary = pars nervosa, pars tuberalis, infundibular stalk) is a downgrowth from the floor of the diencephalon (neuroectoderm). Craniopharyngioma arises from Rathke's pouch remnants, causing visual field defects and endocrine dysfunction.", difficulty:"medium"},
  { id:"ana_178", text:"The tympanic membrane (eardrum) is composed of how many layers?", options:["2 layers","3 layers (pars tensa)","4 layers","Single layer of fibrous tissue"], correct:1, explanation:"The tympanic membrane has 3 layers (pars tensa): outer - stratified squamous epithelium (continuous with external canal skin); middle - fibrous layer (radial and circular collagen fibers); inner - simple cuboidal/flattened mucosa (continuous with middle ear mucosa). The pars flaccida (Shrapnell's membrane) at the top lacks the middle fibrous layer. The handle of the malleus is attached to the membrane.", difficulty:"medium"},
  { id:"ana_179", text:"A posterior dislocation of the hip joint is most likely to injure which nerve?", options:["Femoral nerve","Obturator nerve","Sciatic nerve","Lateral femoral cutaneous nerve"], correct:2, explanation:"The sciatic nerve exits the greater sciatic foramen below piriformis and runs posterior to the hip joint. Posterior hip dislocation (most common type, from dashboard injury with hip flexed and adducted) can stretch or tear the sciatic nerve, causing foot drop (common fibular division is most vulnerable due to its more fixed position). The femoral nerve is anterior and less vulnerable.", difficulty:"easy"},
  { id:"ana_180", text:"The ependymal cells lining the ventricular system produce which fluid?", options:["Blood","Cerebrospinal fluid (CSF)","Lymph","Synovial fluid"], correct:1, explanation:"CSF is produced by the choroid plexus (specialized ependymal cells in the lateral, third, and fourth ventricles) at 500mL/day; total volume ~150mL is circulated and replaced ~3-4x/day. Choroid plexus epithelium has tight junctions (blood-CSF barrier). CSF flows: lateral ventricles → foramen of Monro → third ventricle → aqueduct of Sylvius → fourth ventricle → foramina of Magendie and Luschka → subarachnoid space.", difficulty:"easy"}
];
